INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u7-C1','kor',1,1,'u7',1,'낱말 하나로는 잘 통하지 않는 말 — 「당근!」·「물!」처럼 낱말 하나만 말하면 무엇을 어떻게 하라는지 알 수 없어 듣는 사람이 헷갈릴 수 있음을 알기',ARRAY['2국03-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u7-C2','kor',1,1,'u7',1,'문장으로 말해 뜻을 정확히 전하기 — 낱말을 늘어놓거나 길게만 말하지 않고 누가·무엇을·어찌하는지 이어 문장으로 말하며, 그림에 어울리면 친구와 다른 문장도 맞음을 알기',ARRAY['2국03-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u7-C3','kor',1,1,'u7',3,'쌍받침 ㄲ·ㅆ이 든 낱말 읽고 쓰기 — 받침 자리에 같은 자음자 두 개가 겹친 쌍받침(밖·낚시·닦다·묶다 / 갔다·있다·샀다)을 알아보고 홑받침과 가려 바르게 읽고 쓰기',ARRAY['2국04-03']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u7-C4','kor',1,1,'u7',4,'그림에 알맞은 낱말 찾기 — 그림을 자세히 보고 떠오르는 낱말을 첫 글자만이 아니라 끝 글자까지 그림과 맞춰 보며(장갑·장화, 우산·우유) 알맞은 낱말 고르기',ARRAY['2국03-01']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u7-C5','kor',1,1,'u7',4,'앞뒤 말과 어울리는 낱말로 문장 완성 — 빈칸 앞뒤의 말과 그림을 함께 살펴 뜻이 통하는 낱말을 넣고(연을 날려요·물을 마셔요), 다 넣은 뒤 소리 내어 읽어 어색한지 확인하기',ARRAY['2국03-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u7-C6','kor',1,1,'u7',6,'「무엇은 무엇입니다」·「무엇은 어떠합니다」로 말하기 — 낱말이 어느 무리에 드는지(복숭아는 과일입니다), 어떠한지(얼음은 차갑습니다) 알맞은 낱말을 넣어 말하고 두 틀을 섞지 않기',ARRAY['2국03-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u7-C7','kor',1,1,'u7',6,'「누가 무엇을 합니다」 조각 채우기 — 그림을 보고 누가·무엇을·어찌하다 조각에 알맞은 낱말을 넣으며, 「무엇을」을 빠뜨리거나 누가와 무엇을을 바꿔 넣지 않기',ARRAY['2국03-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u7-C8','kor',1,1,'u7',9,'이야기 장면을 알맞은 낱말로 문장 만들기 — 이야기에서 누가·어디에서·무엇을 했는지 찾고 낯선 낱말의 뜻을 알아(눈보라·들판) 장면에 맞는 문장을 만들기',ARRAY['2국03-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u7-C9','kor',1,1,'u7',11,'낱말 카드로 자연스러운 문장 만들기 — 누가(노란색)·무엇을(분홍색)·어찌하다(하늘색) 카드를 차례대로 놓아 문장을 만들고, 엉뚱하게 이어진 문장은 어울리는 카드로 바꿔 자연스럽게 고치기',ARRAY['2국03-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u7-C10','kor',1,1,'u7',13,'「무엇을」과 어울리는 「어찌하다」 — 몸에 걸치는 말(모자를 쓰다·옷을 입다·신발을 신다·장갑을 끼다·시계를 차다)과 하는 일(연을 날리다·피리를 불다·신발 끈을 묶다)의 짝을 알맞게 쓰기',ARRAY['2국04-03']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u7-X01','kor',1,'u7',ARRAY['K1-1-u7-C1','K1-1-u7-C2']::text[],'낱말 하나만 말해도 뜻이 다 통한다고 여겨 「물!」·「공!」처럼 낱말만 말한다','낱말 뒤에 「무엇을? 어떻게?」를 붙여 한 문장으로 다시 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u7-X02','kor',1,'u7',ARRAY['K1-1-u7-C2']::text[],'낱말을 늘어놓거나 길게만 말하면 문장이 된다고 여겨 뜻이 통하는지 살피지 않는다(공, 나, 던져)','말한 뒤 「누가? 무엇을? 어찌하나?」가 이어지는지 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u7-X03','kor',1,'u7',ARRAY['K1-1-u7-C3']::text[],'쌍받침을 홑받침 하나로 쓴다(낚시 → 낙시, 갔다 → 갓다, 밖 → 박)','받침 자리에 같은 자음자를 두 번 나란히 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u7-X04','kor',1,'u7',ARRAY['K1-1-u7-C3']::text[],'쌍받침 ㄲ과 ㅆ을 서로 바꿔 쓰거나 헷갈린다(있다 → 읶다, 닦다 → 닸다)','「ㄱ 두 개는 ㄲ, ㅅ 두 개는 ㅆ」 받침 모양을 손가락으로 따라 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u7-X05','kor',1,'u7',ARRAY['K1-1-u7-C4']::text[],'첫 글자만 보고 낱말을 고른다(장갑 ↔ 장화, 우산 ↔ 우유)','끝 글자까지 소리 내어 읽고 그림과 하나씩 맞춰 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u7-X06','kor',1,'u7',ARRAY['K1-1-u7-C2','K1-1-u7-C4','K1-1-u7-C5','K1-1-u7-C7']::text[],'그림이나 상황을 끝까지 살피지 않고 그림에 없거나 맞지 않는 낱말을 넣는다','그림에서 누가·무엇을·어떻게 하는지 먼저 말한 뒤 낱말 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u7-X07','kor',1,'u7',ARRAY['K1-1-u7-C5','K1-1-u7-C7','K1-1-u7-C8','K1-1-u7-C9','K1-1-u7-C10']::text[],'「무엇을」과 어울리지 않는 「어찌하다」를 넣는다(연을 마셔요, 피리를 쳐요, 노래를 먹어요)','「무엇을」과 「어찌하다」만 떼어 소리 내어 읽어 보고 어색한지 살피기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u7-X08','kor',1,'u7',ARRAY['K1-1-u7-C6']::text[],'「무엇은 무엇입니다」에서 알맞지 않은 무리를 고른다(복숭아는 채소입니다, 오리는 과일입니다)','「○○는 □□ 가운데 하나인가?」 스스로 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u7-X09','kor',1,'u7',ARRAY['K1-1-u7-C6']::text[],'「무엇은 무엇입니다」와 「누가 무엇을 합니다」 두 틀을 섞어 쓴다(토끼는 당근을 입니다)','문장을 끝까지 소리 내어 읽고 어느 틀인지 먼저 정하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u7-X10','kor',1,'u7',ARRAY['K1-1-u7-C7']::text[],'「누가 무엇을 합니다」에서 「무엇을」 조각을 빠뜨린다(다람쥐가 먹습니다)','「무엇을?」 하고 되물어 가운데 조각 채우기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u7-X11','kor',1,'u7',ARRAY['K1-1-u7-C7','K1-1-u7-C8','K1-1-u7-C9']::text[],'「누가」와 「무엇을」을 바꿔 넣거나 붙는 말(~이·가 / ~을·를)을 바꿔 쓴다(하늘이 새를 날아갑니다)','움직이는 쪽에 「~이·~가」, 받는 쪽에 「~을·~를」 붙이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u7-X12','kor',1,'u7',ARRAY['K1-1-u7-C8']::text[],'이야기를 끝까지 살피지 않아 나오지 않은 일이나 장소로 문장을 만든다','「누가? 어디에서? 무엇을?」을 이야기에서 찾아 손가락으로 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u7-X13','kor',1,'u7',ARRAY['K1-1-u7-C8']::text[],'낯선 낱말의 뜻을 글자 모양만 보고 짐작한다(눈보라 = 보라색 눈)','낱말이 나온 앞뒤 문장을 다시 읽고 장면을 떠올려 뜻 짐작하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u7-X14','kor',1,'u7',ARRAY['K1-1-u7-C9']::text[],'낱말 카드의 구실(누가·무엇을·어찌하다)과 놓는 차례를 헷갈린다','노란색 → 분홍색 → 하늘색 차례로 카드를 한 장씩 짚으며 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u7-X15','kor',1,'u7',ARRAY['K1-1-u7-C10']::text[],'몸에 걸치는 말(입다·신다·쓰다·끼다·차다)을 서로 바꿔 쓴다(장갑을 신다, 모자를 입다)','몸 어디에 걸치는지 손으로 짚으며 짝을 소리 내어 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u7-X16','kor',1,'u7',ARRAY['K1-1-u7-C2','K1-1-u7-C9']::text[],'그림과 어울리고 뜻이 통해도 친구나 보기와 다른 문장은 틀렸다고 여긴다','「그림과 어울리나? 뜻이 통하나?」 두 가지만 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_basic#1','kor',1,1,'u7','L01','g1_1_kor_u7_L01_basic','lesson_basic','K1-1-u7-C1',1,'mc','auto','요리하던 곰이 「당근!」이라고만 말했어요. 곰이 무엇을 하라는 것인지 알 수 있나요?',ARRAY['K1-1-u7-X01']::text[],true,'{"seq":1,"concept":"K1-1-u7-C1","difficulty":1,"kind":"mc","stem":"요리하던 곰이 「당근!」이라고만 말했어요. 곰이 무엇을 하라는 것인지 알 수 있나요?","options":[{"t":"알 수 없어요 — 달라는 건지 씻으라는 건지 몰라요","correct":true},{"t":"네, 당근을 먹으라는 뜻이에요","mis":"K1-1-u7-X01"},{"t":"네, 낱말 하나면 뜻이 다 통해요","mis":"K1-1-u7-X01"}],"explanation":["「당근!」만으로는 무엇을 어떻게 하라는지 알 수 없어요.","낱말 하나로는 듣는 사람마다 다르게 알아들을 수 있어요.","「당근을 씻어 줘.」처럼 문장으로 말하면 잘 통해요."],"asset":{"type":"scene","icon":"🐻🥕🍲"},"variant_rule":{"alt":[{"stem":"운동장에서 친구가 「공!」이라고만 외쳤어요. 친구가 무엇을 하라는 것인지 알 수 있나요?","options":[{"t":"알 수 없어요 — 던지라는 건지 비키라는 건지 몰라요","correct":true},{"t":"네, 공을 차라는 뜻이에요","mis":"K1-1-u7-X01"},{"t":"네, 낱말 하나면 뜻이 다 통해요","mis":"K1-1-u7-X01"}],"explanation":["「공!」만으로는 무엇을 어떻게 하라는지 알 수 없어요.","던져, 잡아, 비켜 — 여러 뜻이 될 수 있어요.","「공을 나에게 던져 줘.」처럼 문장으로 말하면 잘 통해요."],"asset":{"type":"scene","icon":"⚽🧒🧒"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_basic#2','kor',1,1,'u7','L01','g1_1_kor_u7_L01_basic','lesson_basic','K1-1-u7-C1',1,'ox','auto','낱말 하나만 말해도 내 뜻은 언제나 잘 전해져요.',ARRAY['K1-1-u7-X01']::text[],true,'{"seq":2,"concept":"K1-1-u7-C1","difficulty":1,"kind":"ox","stem":"낱말 하나만 말해도 내 뜻은 언제나 잘 전해져요.","answer":"X","reason_options":[{"t":"낱말 하나로는 무엇을 어떻게 하라는지 알 수 없을 때가 많으니까","correct":true},{"t":"말이 짧을수록 더 잘 알아들으니까","mis":"K1-1-u7-X01"}],"mis":"K1-1-u7-X01","explanation":["낱말 하나로는 뜻이 잘 전해지지 않을 때가 많아요.","짧다고 더 잘 통하는 것이 아니에요.","무엇을 어떻게 하고 싶은지 문장으로 말해요."],"variant_rule":{"alt":[{"stem":"「물!」이라고만 말하면 마실 물을 달라는 건지, 쏟은 물을 닦으라는 건지 헷갈릴 수 있어요.","answer":"O","reason_options":[{"t":"낱말 하나로는 무엇을 하라는지 알 수 없으니까","correct":true},{"t":"물은 언제나 마시는 것이니까","mis":"K1-1-u7-X01"}],"explanation":["「물!」은 여러 뜻으로 알아들을 수 있어요.","「물을 마시고 싶어요.」처럼 말해야 정확해요.","무엇을 어떻게 하고 싶은지 문장으로 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_basic#3','kor',1,1,'u7','L01','g1_1_kor_u7_L01_basic','lesson_basic','K1-1-u7-C2',1,'mc','auto','그림에 알맞은 문장은 어느 것인가요?',ARRAY['K1-1-u7-X02','K1-1-u7-X06']::text[],true,'{"seq":3,"concept":"K1-1-u7-C2","difficulty":1,"kind":"mc","stem":"그림에 알맞은 문장은 어느 것인가요?","options":[{"t":"아이가 책을 읽어요.","correct":true},{"t":"책, 아이.","mis":"K1-1-u7-X02"},{"t":"아이가 공을 차요.","mis":"K1-1-u7-X06"}],"explanation":["그림 속 아이는 책을 읽고 있어요.","낱말만 늘어놓거나 그림과 다른 일을 말하면 뜻이 잘 통하지 않아요.","누가 무엇을 하는지 문장으로 말해요."],"asset":{"type":"scene","icon":"📖🧒"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림에 알맞은 문장은 어느 것인가요?","options":[{"t":"강아지가 뛰어가요.","correct":true},{"t":"강아지, 마당.","mis":"K1-1-u7-X02"},{"t":"강아지가 잠을 자요.","mis":"K1-1-u7-X06"}],"explanation":["그림 속 강아지는 뛰어가고 있어요.","낱말만 늘어놓거나 그림과 다른 일을 말하면 뜻이 잘 통하지 않아요.","누가 무엇을 하는지 문장으로 말해요."],"asset":{"type":"scene","icon":"🐶💨"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_basic#4','kor',1,1,'u7','L01','g1_1_kor_u7_L01_basic','lesson_basic','K1-1-u7-C2',1,'mc','auto','목이 말라 물을 마시고 싶어요. 뜻이 가장 잘 전해지는 말은 어느 것인가요?',ARRAY['K1-1-u7-X01','K1-1-u7-X02']::text[],true,'{"seq":4,"concept":"K1-1-u7-C2","difficulty":1,"kind":"mc","stem":"목이 말라 물을 마시고 싶어요. 뜻이 가장 잘 전해지는 말은 어느 것인가요?","options":[{"t":"물 좀 주세요.","correct":true},{"t":"물!","mis":"K1-1-u7-X01"},{"t":"물, 컵, 나.","mis":"K1-1-u7-X02"}],"explanation":["「물 좀 주세요.」는 무엇을 원하는지 또렷하게 전해요.","낱말 하나나 늘어놓은 낱말로는 뜻이 흐려요.","하고 싶은 것을 문장으로 말해요."],"variant_rule":{"alt":[{"stem":"친구가 가진 사과를 하나 얻고 싶어요. 뜻이 가장 잘 전해지는 말은 어느 것인가요?","options":[{"t":"사과 하나만 나에게 줄래?","correct":true},{"t":"사과!","mis":"K1-1-u7-X01"},{"t":"사과, 하나, 나.","mis":"K1-1-u7-X02"}],"explanation":["「사과 하나만 나에게 줄래?」는 무엇을 원하는지 또렷하게 전해요.","낱말 하나나 늘어놓은 낱말로는 뜻이 흐려요.","하고 싶은 것을 문장으로 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_basic#5','kor',1,1,'u7','L01','g1_1_kor_u7_L01_basic','lesson_basic','K1-1-u7-C2',2,'mc','auto','문장으로 말하면 좋은 점은 무엇인가요?',ARRAY['K1-1-u7-X01','K1-1-u7-X02']::text[],true,'{"seq":5,"concept":"K1-1-u7-C2","difficulty":2,"kind":"mc","stem":"문장으로 말하면 좋은 점은 무엇인가요?","options":[{"t":"내 생각을 정확하게 전할 수 있어요","correct":true},{"t":"말이 짧아져서 빨리 끝나요","mis":"K1-1-u7-X01"},{"t":"어려운 낱말을 많이 쓸 수 있어요","mis":"K1-1-u7-X02"}],"explanation":["문장으로 말하면 무엇을 어떻게 하고 싶은지 정확히 전해져요.","짧게 끝내거나 어려운 낱말을 쓰려고 문장으로 말하는 것이 아니에요.","누가·무엇을·어찌하는지 이어 말해요."],"variant_rule":{"alt":[{"stem":"낱말만 말했을 때 생길 수 있는 일은 무엇인가요?","options":[{"t":"듣는 사람이 내 뜻을 잘못 알 수 있어요","correct":true},{"t":"누구나 내 뜻을 바로 알아요","mis":"K1-1-u7-X01"},{"t":"말이 더 정확해져요","mis":"K1-1-u7-X01"}],"explanation":["낱말만 말하면 듣는 사람이 뜻을 잘못 알 수 있어요.","낱말 하나로 더 정확해지지는 않아요.","그래서 문장으로 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_basic#6','kor',1,1,'u7','L01','g1_1_kor_u7_L01_basic','lesson_basic','K1-1-u7-C2',2,'match','auto','낱말만 한 말과 뜻이 잘 통하는 문장을 이으세요.','{}'::text[],true,'{"seq":6,"concept":"K1-1-u7-C2","difficulty":2,"kind":"match","stem":"낱말만 한 말과 뜻이 잘 통하는 문장을 이으세요.","pairs":[{"l":"물!","r":"물을 마시고 싶어요."},{"l":"문!","r":"추우니 문을 닫아 주세요."},{"l":"공!","r":"공을 나에게 던져 줘."}],"mis":"K1-1-u7-X01","explanation":["낱말 하나를 문장으로 바꾸면 무엇을 어떻게 할지 알 수 있어요.","같은 낱말이 들어간 문장끼리 이어요.","낱말 뒤에 「무엇을? 어떻게?」를 붙여 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말만 한 말과 뜻이 잘 통하는 문장을 이으세요.","pairs":[{"l":"불!","r":"방에 불을 켜 주세요."},{"l":"창문!","r":"창문을 열어 주세요."},{"l":"연필!","r":"연필 좀 빌려줄래?"}],"explanation":["낱말 하나를 문장으로 바꾸면 무엇을 어떻게 할지 알 수 있어요.","같은 낱말이 들어간 문장끼리 이어요.","낱말 뒤에 「무엇을? 어떻게?」를 붙여 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_basic#7','kor',1,1,'u7','L01','g1_1_kor_u7_L01_basic','lesson_basic','K1-1-u7-C2',2,'mc','auto','그림을 「누가 무엇을 합니다」로 바르게 말한 것은 어느 것인가요?',ARRAY['K1-1-u7-X02','K1-1-u7-X06']::text[],true,'{"seq":7,"concept":"K1-1-u7-C2","difficulty":2,"kind":"mc","stem":"그림을 「누가 무엇을 합니다」로 바르게 말한 것은 어느 것인가요?","options":[{"t":"친구가 그림을 그립니다.","correct":true},{"t":"친구, 그림.","mis":"K1-1-u7-X02"},{"t":"친구가 노래를 부릅니다.","mis":"K1-1-u7-X06"}],"explanation":["그림 속 친구는 그림을 그리고 있어요.","낱말만 늘어놓거나 그림과 다른 일을 말하면 안 돼요.","누가·무엇을·어찌하는지 차례로 말해요."],"asset":{"type":"scene","icon":"🧒🎨"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림을 「누가 무엇을 합니다」로 바르게 말한 것은 어느 것인가요?","options":[{"t":"동생이 우유를 마십니다.","correct":true},{"t":"동생, 우유.","mis":"K1-1-u7-X02"},{"t":"동생이 우유를 쏟습니다.","mis":"K1-1-u7-X06"}],"explanation":["그림 속 동생은 우유를 마시고 있어요.","낱말만 늘어놓거나 그림과 다른 일을 말하면 안 돼요.","누가·무엇을·어찌하는지 차례로 말해요."],"asset":{"type":"scene","icon":"👶🥛"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_basic#8','kor',1,1,'u7','L01','g1_1_kor_u7_L01_basic','lesson_basic','K1-1-u7-C1',2,'ox','auto','「당근!」과 「당근을 씻어 주세요.」 가운데 뜻이 더 잘 통하는 것은 「당근!」이에요.',ARRAY['K1-1-u7-X01']::text[],false,'{"seq":8,"concept":"K1-1-u7-C1","difficulty":2,"kind":"ox","stem":"「당근!」과 「당근을 씻어 주세요.」 가운데 뜻이 더 잘 통하는 것은 「당근!」이에요.","answer":"X","reason_options":[{"t":"「당근을 씻어 주세요.」는 무엇을 어떻게 할지 알려 주니까","correct":true},{"t":"짧은 말이 언제나 더 잘 통하니까","mis":"K1-1-u7-X01"}],"mis":"K1-1-u7-X01","explanation":["「당근을 씻어 주세요.」가 뜻이 더 잘 통해요.","「당근!」만으로는 무엇을 하라는지 몰라요.","무엇을 어떻게 할지 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_basic#9','kor',1,1,'u7','L01','g1_1_kor_u7_L01_basic','lesson_basic','K1-1-u7-C2',2,'mc','auto','추운 날 열린 문을 보고 친구에게 하고 싶은 말이에요. 「문!」을 알맞은 문장으로 바꾼 것은 어느 것인가요?',ARRAY['K1-1-u7-X02','K1-1-u7-X06']::text[],true,'{"seq":9,"concept":"K1-1-u7-C2","difficulty":2,"kind":"mc","stem":"추운 날 열린 문을 보고 친구에게 하고 싶은 말이에요. 「문!」을 알맞은 문장으로 바꾼 것은 어느 것인가요?","options":[{"t":"추우니까 문을 닫아 줄래?","correct":true},{"t":"문, 추워, 닫아.","mis":"K1-1-u7-X02"},{"t":"문을 활짝 열어 줘.","mis":"K1-1-u7-X06"}],"explanation":["추운 날이니 문을 닫아 달라고 말해요.","낱말만 늘어놓거나 상황과 반대로 말하면 뜻이 잘못 전해져요.","상황을 살펴 하고 싶은 말을 문장으로 해요."],"variant_rule":{"alt":[{"stem":"방이 깜깜해서 동생에게 하고 싶은 말이에요. 「불!」을 알맞은 문장으로 바꾼 것은 어느 것인가요?","options":[{"t":"깜깜하니까 불을 켜 줄래?","correct":true},{"t":"불, 깜깜, 켜.","mis":"K1-1-u7-X02"},{"t":"불을 꺼 줘.","mis":"K1-1-u7-X06"}],"explanation":["깜깜하니 불을 켜 달라고 말해요.","낱말만 늘어놓거나 상황과 반대로 말하면 뜻이 잘못 전해져요.","상황을 살펴 하고 싶은 말을 문장으로 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_basic#10','kor',1,1,'u7','L01','g1_1_kor_u7_L01_basic','lesson_basic','K1-1-u7-C2',3,'error','auto','하린이가 운동장에서 친구에게 공을 던져 달라며 이렇게 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_challenge#1','kor',1,1,'u7','L01','g1_1_kor_u7_L01_challenge','lesson_challenge','K1-1-u7-C1',2,'mc','auto','친구가 「공!」이라고만 외쳤을 때 헷갈리는 까닭은 무엇인가요?',ARRAY['K1-1-u7-X01']::text[],false,'{"seq":1,"concept":"K1-1-u7-C1","difficulty":2,"kind":"mc","stem":"친구가 「공!」이라고만 외쳤을 때 헷갈리는 까닭은 무엇인가요?","options":[{"t":"공을 던지라는 건지, 잡으라는 건지, 비키라는 건지 알 수 없어서","correct":true},{"t":"공이라는 낱말을 처음 들어서","mis":"K1-1-u7-X01"},{"t":"목소리가 너무 커서","mis":"K1-1-u7-X01"}],"explanation":["「공!」은 여러 뜻으로 알아들을 수 있어요.","낱말을 몰라서나 목소리 때문이 아니에요.","무엇을 어떻게 할지 문장으로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_challenge#2','kor',1,1,'u7','L01','g1_1_kor_u7_L01_challenge','lesson_challenge','K1-1-u7-C2',2,'mc','auto','곰이 당근을 씻어 달라고 하는 그림이에요. 뜻이 가장 잘 통하는 말은 어느 것인가요?',ARRAY['K1-1-u7-X01','K1-1-u7-X02']::text[],false,'{"seq":2,"concept":"K1-1-u7-C2","difficulty":2,"kind":"mc","stem":"곰이 당근을 씻어 달라고 하는 그림이에요. 뜻이 가장 잘 통하는 말은 어느 것인가요?","options":[{"t":"당근을 깨끗이 씻어 줘.","correct":true},{"t":"당근!","mis":"K1-1-u7-X01"},{"t":"당근, 물, 씻어.","mis":"K1-1-u7-X02"}],"explanation":["「당근을 깨끗이 씻어 줘.」는 무엇을 어떻게 할지 알려 줘요.","낱말 하나나 늘어놓은 낱말로는 뜻이 흐려요.","문장으로 말해요."],"asset":{"type":"scene","icon":"🐻🥕💧"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_challenge#3','kor',1,1,'u7','L01','g1_1_kor_u7_L01_challenge','lesson_challenge','K1-1-u7-C2',3,'mc','auto','토끼가 당근을 먹는 그림이에요. 그림에 어울리는 문장이 아닌 것은 어느 것인가요?',ARRAY['K1-1-u7-X16']::text[],false,'{"seq":3,"concept":"K1-1-u7-C2","difficulty":3,"kind":"mc","stem":"토끼가 당근을 먹는 그림이에요. 그림에 어울리는 문장이 아닌 것은 어느 것인가요?","options":[{"t":"토끼가 당근을 심어요.","correct":true},{"t":"토끼가 당근을 먹어요.","mis":"K1-1-u7-X16"},{"t":"토끼가 맛있게 당근을 먹어요.","mis":"K1-1-u7-X16"}],"explanation":["그림 속 토끼는 당근을 먹고 있어요. 심는 모습이 아니에요.","「토끼가 맛있게 당근을 먹어요.」도 그림과 어울리는 문장이에요.","그림과 어울리면 서로 다른 문장도 모두 맞아요."],"asset":{"type":"scene","icon":"🐰🥕"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_challenge#4','kor',1,1,'u7','L01','g1_1_kor_u7_L01_challenge','lesson_challenge','K1-1-u7-C2',3,'ox','auto','같은 그림을 보고도 친구와 내가 서로 다른 문장을 만들 수 있어요.',ARRAY['K1-1-u7-X16']::text[],false,'{"seq":4,"concept":"K1-1-u7-C2","difficulty":3,"kind":"ox","stem":"같은 그림을 보고도 친구와 내가 서로 다른 문장을 만들 수 있어요.","answer":"O","reason_options":[{"t":"그림과 어울리고 뜻이 통하면 다른 문장도 모두 맞으니까","correct":true},{"t":"그림 하나에는 맞는 문장이 하나뿐이니까","mis":"K1-1-u7-X16"}],"mis":"K1-1-u7-X16","explanation":["같은 그림이라도 여러 문장으로 말할 수 있어요.","그림과 어울리고 뜻이 통하면 모두 맞아요.","친구 문장과 달라도 괜찮아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_challenge#5','kor',1,1,'u7','L01','g1_1_kor_u7_L01_challenge','lesson_challenge','K1-1-u7-C2',3,'error','auto','시우가 그림을 보고 길게 말하면 문장이 된다고 생각해 이렇게 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_challenge#6','kor',1,1,'u7','L01','g1_1_kor_u7_L01_challenge','lesson_challenge','K1-1-u7-C2',3,'mc','auto','「사과」를 넣어 뜻이 잘 통하는 문장으로 말한 것은 어느 것인가요?',ARRAY['K1-1-u7-X02']::text[],false,'{"seq":6,"concept":"K1-1-u7-C2","difficulty":3,"kind":"mc","stem":"「사과」를 넣어 뜻이 잘 통하는 문장으로 말한 것은 어느 것인가요?","options":[{"t":"나는 사과를 먹어요.","correct":true},{"t":"사과 사과 사과.","mis":"K1-1-u7-X02"},{"t":"사과, 빨개, 나.","mis":"K1-1-u7-X02"}],"explanation":["「나는 사과를 먹어요.」는 누가 무엇을 어찌하는지 다 있어요.","같은 낱말을 되풀이하거나 늘어놓으면 문장이 아니에요.","낱말을 이어 뜻이 통하게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_challenge#7','kor',1,1,'u7','L01','g1_1_kor_u7_L01_challenge','lesson_challenge','K1-1-u7-C2',3,'mc','auto','가게에서 빵 하나를 사려고 해요. 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K1-1-u7-X01','K1-1-u7-X02']::text[],false,'{"seq":7,"concept":"K1-1-u7-C2","difficulty":3,"kind":"mc","stem":"가게에서 빵 하나를 사려고 해요. 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"빵 하나 주세요.","correct":true},{"t":"빵!","mis":"K1-1-u7-X01"},{"t":"빵, 하나, 돈.","mis":"K1-1-u7-X02"}],"explanation":["「빵 하나 주세요.」는 무엇을 얼마나 원하는지 또렷해요.","낱말 하나나 늘어놓은 낱말로는 뜻이 흐려요.","가게에서도 문장으로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_challenge#8','kor',1,1,'u7','L01','g1_1_kor_u7_L01_challenge','lesson_challenge','K1-1-u7-C2',4,'mc','auto','두 친구의 말을 견주어 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_challenge#9','kor',1,1,'u7','L01','g1_1_kor_u7_L01_challenge','lesson_challenge','K1-1-u7-C1',4,'essay','teacher','낱말 하나만 말해서 뜻이 잘 통하지 않았던 일을 떠올려 쓰고, 그 말을 문장으로 바꾸어 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u7-C1","difficulty":4,"kind":"essay","stem":"낱말 하나만 말해서 뜻이 잘 통하지 않았던 일을 떠올려 쓰고, 그 말을 문장으로 바꾸어 써 보세요.","answer_guide":{"answer":"예: 동생에게 「불!」이라고만 해서 동생이 무슨 뜻인지 몰랐어요. → 「방이 깜깜하니까 불을 켜 줄래?」","scoring_points":["낱말만 말했던 일을 썼는가","왜 잘 통하지 않았는지 드러났는가","뜻이 통하는 문장으로 바꾸어 썼는가"]},"explanation":["낱말만 말한 일.","잘 통하지 않은 까닭.","문장으로 바꾸기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L01_challenge#10','kor',1,1,'u7','L01','g1_1_kor_u7_L01_challenge','lesson_challenge','K1-1-u7-C2',4,'essay','teacher','그림을 보고 「누가 무엇을 합니다」 문장을 서로 다르게 두 가지 만들어 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u7-C2","difficulty":4,"kind":"essay","stem":"그림을 보고 「누가 무엇을 합니다」 문장을 서로 다르게 두 가지 만들어 써 보세요.","answer_guide":{"answer":"예: 아이가 그림을 그립니다. / 고양이가 아이를 봅니다.","scoring_points":["그림과 어울리는 문장을 썼는가","누가·무엇을·어찌하다가 다 들어갔는가","두 문장이 서로 다른가"]},"explanation":["그림과 어울리기.","세 조각.","서로 다른 두 문장."],"asset":{"type":"scene","icon":"👧🎨🐱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L03_basic#1','kor',1,1,'u7','L03','g1_1_kor_u7_L03_basic','lesson_basic','K1-1-u7-C3',1,'mc','auto','쌍받침이 든 글자는 어느 것인가요?',ARRAY['K1-1-u7-X03']::text[],true,'{"seq":1,"concept":"K1-1-u7-C3","difficulty":1,"kind":"mc","stem":"쌍받침이 든 글자는 어느 것인가요?","options":[{"t":"밖","correct":true},{"t":"박","mis":"K1-1-u7-X03"},{"t":"바","mis":"K1-1-u7-X03"}],"explanation":["「밖」은 받침 자리에 ㄱ 두 개가 겹친 쌍받침 ㄲ이 있어요.","「박」은 받침 ㄱ 하나, 「바」는 받침이 없어요.","받침 자리에 같은 자음자가 두 개인지 살펴요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 쌍받침이 든 글자는 어느 것인가요?","options":[{"t":"낚","correct":true},{"t":"낙","mis":"K1-1-u7-X03"},{"t":"나","mis":"K1-1-u7-X03"}],"explanation":["「낚」은 받침 자리에 ㄱ 두 개가 겹친 쌍받침 ㄲ이 있어요.","「낙」은 받침 ㄱ 하나, 「나」는 받침이 없어요.","받침 자리에 같은 자음자가 두 개인지 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L03_basic#2','kor',1,1,'u7','L03','g1_1_kor_u7_L03_basic','lesson_basic','K1-1-u7-C3',1,'mc','auto','그림에 알맞은 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-1-u7-X03','K1-1-u7-X04']::text[],true,'{"seq":2,"concept":"K1-1-u7-C3","difficulty":1,"kind":"mc","stem":"그림에 알맞은 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"낚시","correct":true},{"t":"낙시","mis":"K1-1-u7-X03"},{"t":"났시","mis":"K1-1-u7-X04"}],"explanation":["물고기를 잡는 일은 「낚시」예요. 받침이 ㄲ이에요.","「낙시」는 ㄱ 하나만, 「났시」는 ㄲ 대신 ㅆ을 썼어요.","받침 자리에 ㄱ 두 개를 나란히 써요."],"asset":{"type":"scene","icon":"🎣🐟"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림에 알맞은 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"깎다","correct":true},{"t":"깍다","mis":"K1-1-u7-X03"},{"t":"깠다","mis":"K1-1-u7-X04"}],"explanation":["손톱을 자르는 일은 「깎다」예요. 받침이 ㄲ이에요.","「깍다」는 ㄱ 하나만, 「깠다」는 ㄲ 대신 ㅆ을 썼어요.","받침 자리에 ㄱ 두 개를 나란히 써요."],"asset":{"type":"scene","icon":"✂️💅"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L03_basic#3','kor',1,1,'u7','L03','g1_1_kor_u7_L03_basic','lesson_basic','K1-1-u7-C3',1,'ox','auto','「밖」의 받침은 ㄱ이 두 개 겹친 쌍받침 ㄲ이에요.',ARRAY['K1-1-u7-X03']::text[],true,'{"seq":3,"concept":"K1-1-u7-C3","difficulty":1,"kind":"ox","stem":"「밖」의 받침은 ㄱ이 두 개 겹친 쌍받침 ㄲ이에요.","answer":"O","reason_options":[{"t":"받침 자리에 ㄱ 두 개가 나란히 있으니까","correct":true},{"t":"받침은 언제나 한 개뿐이니까","mis":"K1-1-u7-X03"}],"mis":"K1-1-u7-X03","explanation":["「밖」의 받침은 쌍받침 ㄲ이에요.","받침 자리에도 같은 자음자 두 개를 쓸 수 있어요.","받침 모양을 손가락으로 따라 써 봐요."],"variant_rule":{"alt":[{"stem":"「갔다」의 「갔」 받침은 ㅅ 하나예요.","answer":"X","reason_options":[{"t":"「갔」에는 ㅅ 두 개가 겹친 쌍받침 ㅆ이 있으니까","correct":true},{"t":"받침에는 자음자를 하나만 쓰니까","mis":"K1-1-u7-X03"}],"explanation":["「갔」의 받침은 쌍받침 ㅆ이에요.","받침 자리에도 같은 자음자 두 개를 쓸 수 있어요.","받침 모양을 손가락으로 따라 써 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L03_basic#4','kor',1,1,'u7','L03','g1_1_kor_u7_L03_basic','lesson_basic','K1-1-u7-C3',1,'blank','auto','그림을 보고 빈칸에 알맞은 받침을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L03_basic#5','kor',1,1,'u7','L03','g1_1_kor_u7_L03_basic','lesson_basic','K1-1-u7-C3',2,'mc','auto','쌍받침 ㅆ이 든 낱말은 어느 것인가요?',ARRAY['K1-1-u7-X03','K1-1-u7-X04']::text[],true,'{"seq":5,"concept":"K1-1-u7-C3","difficulty":2,"kind":"mc","stem":"쌍받침 ㅆ이 든 낱말은 어느 것인가요?","options":[{"t":"있다","correct":true},{"t":"잇다","mis":"K1-1-u7-X03"},{"t":"읶다","mis":"K1-1-u7-X04"}],"explanation":["「있다」의 「있」에 쌍받침 ㅆ이 있어요.","「잇다」는 받침 ㅅ 하나, 「읶다」는 ㅆ 대신 ㄲ을 썼어요.","ㅅ 두 개가 나란히 있는지 살펴요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 쌍받침 ㅆ이 든 낱말은 어느 것인가요?","options":[{"t":"먹었다","correct":true},{"t":"먹엇다","mis":"K1-1-u7-X03"},{"t":"먹얶다","mis":"K1-1-u7-X04"}],"explanation":["「먹었다」의 「었」에 쌍받침 ㅆ이 있어요.","「먹엇다」는 ㅅ 하나, 「먹얶다」는 ㅆ 대신 ㄲ을 썼어요.","ㅅ 두 개가 나란히 있는지 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L03_basic#6','kor',1,1,'u7','L03','g1_1_kor_u7_L03_basic','lesson_basic','K1-1-u7-C3',2,'match','auto','그림과 바르게 쓴 말을 이으세요.','{}'::text[],true,'{"seq":6,"concept":"K1-1-u7-C3","difficulty":2,"kind":"match","stem":"그림과 바르게 쓴 말을 이으세요.","pairs":[{"l":"🪥","r":"이를 닦다"},{"l":"👟","r":"끈을 묶다"},{"l":"✂️","r":"손톱을 깎다"}],"mis":"K1-1-u7-X03","explanation":["닦다·묶다·깎다는 모두 받침이 쌍받침 ㄲ이에요.","그림이 하는 일을 떠올려 이어요.","받침 자리에 ㄱ 두 개를 써요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림과 바르게 쓴 말을 이으세요.","pairs":[{"l":"🛒","r":"과자를 샀다"},{"l":"🏫","r":"학교에 갔다"},{"l":"🍚","r":"밥을 먹었다"}],"explanation":["샀다·갔다·먹었다는 모두 쌍받침 ㅆ이 들어 있어요.","그림이 하는 일을 떠올려 이어요.","받침 자리에 ㅅ 두 개를 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
