INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L03_basic#8','kor',1,1,'u7','L03','g1_1_kor_u7_L03_basic','lesson_basic','K1-1-u7-C3',2,'sa','auto','「밖」에 든 쌍받침을 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-1-u7-C3","difficulty":2,"kind":"sa","stem":"「밖」에 든 쌍받침을 쓰세요.","answer":["ㄲ"],"explanation":["「밖」의 받침은 ㄱ 두 개가 겹친 ㄲ이에요.","ㄱ 하나만 쓰면 「박」이 돼요.","받침 모양을 따라 써 봐요."],"variant_rule":{"alt":[{"stem":"「갔」에 든 쌍받침을 쓰세요.","answer":["ㅆ"],"explanation":["「갔」의 받침은 ㅅ 두 개가 겹친 ㅆ이에요.","ㅅ 하나만 쓰면 「갓」이 돼요.","받침 모양을 따라 써 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L03_basic#9','kor',1,1,'u7','L03','g1_1_kor_u7_L03_basic','lesson_basic','K1-1-u7-C3',2,'mc','auto','쌍받침이 든 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K1-1-u7-X03']::text[],true,'{"seq":9,"concept":"K1-1-u7-C3","difficulty":2,"kind":"mc","stem":"쌍받침이 든 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"밖 · 있다","correct":true},{"t":"박 · 잇다","mis":"K1-1-u7-X03"},{"t":"밥 · 있다","mis":"K1-1-u7-X03"}],"explanation":["「밖」에는 ㄲ, 「있다」에는 ㅆ 쌍받침이 있어요.","「박」·「잇다」·「밥」은 받침이 하나예요.","두 낱말 모두 쌍받침인지 살펴요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 쌍받침이 든 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"낚시 · 샀다","correct":true},{"t":"낙시 · 삿다","mis":"K1-1-u7-X03"},{"t":"낚시 · 삽다","mis":"K1-1-u7-X03"}],"explanation":["「낚시」에는 ㄲ, 「샀다」에는 ㅆ 쌍받침이 있어요.","「낙시」·「삿다」·「삽다」는 받침이 하나예요.","두 낱말 모두 쌍받침인지 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
