INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L03_challenge#1','kor',1,1,'u7','L03','g1_1_kor_u7_L03_challenge','lesson_challenge','K1-1-u7-C3',2,'mc','auto','받침 자리에 같은 자음자가 두 개 겹친 받침을 무엇이라고 하나요?',ARRAY['K1-1-u7-X03']::text[],false,'{"seq":1,"concept":"K1-1-u7-C3","difficulty":2,"kind":"mc","stem":"받침 자리에 같은 자음자가 두 개 겹친 받침을 무엇이라고 하나요?","options":[{"t":"쌍받침","correct":true},{"t":"첫 자음자","mis":"K1-1-u7-X03"},{"t":"모음자","mis":"K1-1-u7-X03"}],"explanation":["같은 자음자 두 개가 겹친 받침을 쌍받침이라고 해요.","첫 자음자와 모음자는 받침이 아니에요.","ㄲ·ㅆ이 받침 자리에 오면 쌍받침이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L03_challenge#2','kor',1,1,'u7','L03','g1_1_kor_u7_L03_challenge','lesson_challenge','K1-1-u7-C3',2,'mc','auto','「깎다」에서 쌍받침이 든 글자는 어느 것인가요?',ARRAY['K1-1-u7-X03']::text[],false,'{"seq":2,"concept":"K1-1-u7-C3","difficulty":2,"kind":"mc","stem":"「깎다」에서 쌍받침이 든 글자는 어느 것인가요?","options":[{"t":"깎","correct":true},{"t":"다","mis":"K1-1-u7-X03"},{"t":"쌍받침이 든 글자가 없어요","mis":"K1-1-u7-X03"}],"explanation":["「깎」의 받침이 쌍받침 ㄲ이에요.","「깎」의 첫 자음자도 ㄲ이지만, 받침 자리의 ㄲ이 쌍받침이에요.","받침 자리를 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L03_challenge#3','kor',1,1,'u7','L03','g1_1_kor_u7_L03_challenge','lesson_challenge','K1-1-u7-C3',3,'mc','auto','받침을 잘못 쓴 낱말은 어느 것인가요?',ARRAY['K1-1-u7-X04']::text[],false,'{"seq":3,"concept":"K1-1-u7-C3","difficulty":3,"kind":"mc","stem":"받침을 잘못 쓴 낱말은 어느 것인가요?","options":[{"t":"낙시","correct":true},{"t":"밖","mis":"K1-1-u7-X04"},{"t":"갔다","mis":"K1-1-u7-X04"}],"explanation":["「낙시」는 「낚시」로 써야 해요.","「밖」·「갔다」는 쌍받침을 바르게 썼어요.","받침 자리를 하나씩 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
