INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L03_challenge#6','kor',1,1,'u7','L03','g1_1_kor_u7_L03_challenge','lesson_challenge','K1-1-u7-C3',3,'ox','auto','「밖」과 「박」은 받침만 다를 뿐 뜻은 같아요.',ARRAY['K1-1-u7-X03']::text[],false,'{"seq":6,"concept":"K1-1-u7-C3","difficulty":3,"kind":"ox","stem":"「밖」과 「박」은 받침만 다를 뿐 뜻은 같아요.","answer":"X","reason_options":[{"t":"받침이 ㄲ과 ㄱ으로 달라 뜻도 다른 낱말이니까","correct":true},{"t":"소리가 비슷하면 뜻도 같으니까","mis":"K1-1-u7-X03"}],"mis":"K1-1-u7-X03","explanation":["「밖」은 바깥, 「박」은 다른 뜻의 낱말이에요.","받침 하나로 뜻이 달라져요.","받침을 바르게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L03_challenge#7','kor',1,1,'u7','L03','g1_1_kor_u7_L03_challenge','lesson_challenge','K1-1-u7-C3',3,'mc','auto','쌍받침 ㄲ이 든 낱말과 ㅆ이 든 낱말을 바르게 나눈 것은 어느 것인가요?',ARRAY['K1-1-u7-X04','K1-1-u7-X03']::text[],false,'{"seq":7,"concept":"K1-1-u7-C3","difficulty":3,"kind":"mc","stem":"쌍받침 ㄲ이 든 낱말과 ㅆ이 든 낱말을 바르게 나눈 것은 어느 것인가요?","options":[{"t":"ㄲ: 낚시·묶다 / ㅆ: 갔다·있다","correct":true},{"t":"ㄲ: 낚시·있다 / ㅆ: 갔다·묶다","mis":"K1-1-u7-X04"},{"t":"ㄲ: 낙시·묵다 / ㅆ: 갓다·잇다","mis":"K1-1-u7-X03"}],"explanation":["「낚시·묶다」는 ㄲ, 「갔다·있다」는 ㅆ이에요.","ㄲ과 ㅆ을 바꾸거나 받침을 하나만 쓰면 안 돼요.","ㄱ 두 개는 ㄲ, ㅅ 두 개는 ㅆ이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L03_challenge#8','kor',1,1,'u7','L03','g1_1_kor_u7_L03_challenge','lesson_challenge','K1-1-u7-C3',4,'mc','auto','쌍받침을 모두 바르게 쓴 문장은 어느 것인가요?',ARRAY['K1-1-u7-X03']::text[],false,'{"seq":8,"concept":"K1-1-u7-C3","difficulty":4,"kind":"mc","stem":"쌍받침을 모두 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"동생과 밖에서 놀았다.","correct":true},{"t":"동생과 박에서 놀았다.","mis":"K1-1-u7-X03"},{"t":"동생과 밖에서 놀앗다.","mis":"K1-1-u7-X03"}],"explanation":["「밖」은 ㄲ, 「놀았다」는 ㅆ 쌍받침이에요.","다른 두 보기는 쌍받침 하나를 빠뜨렸어요.","문장 속 받침을 하나씩 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L03_challenge#9','kor',1,1,'u7','L03','g1_1_kor_u7_L03_challenge','lesson_challenge','K1-1-u7-C3',4,'essay','teacher','쌍받침 ㄲ이 든 낱말과 ㅆ이 든 낱말을 하나씩 넣어 문장을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u7-C3","difficulty":4,"kind":"essay","stem":"쌍받침 ㄲ이 든 낱말과 ㅆ이 든 낱말을 하나씩 넣어 문장을 써 보세요.","answer_guide":{"answer":"예: 나는 손톱을 깎고 학교에 갔다.","scoring_points":["ㄲ 쌍받침 낱말을 바르게 썼는가","ㅆ 쌍받침 낱말을 바르게 썼는가","뜻이 통하는 문장인가"]},"explanation":["ㄲ 낱말.","ㅆ 낱말.","뜻이 통하는 문장."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L03_challenge#10','kor',1,1,'u7','L03','g1_1_kor_u7_L03_challenge','lesson_challenge','K1-1-u7-C3',4,'essay','teacher','「낚시」를 「낙시」로 쓰면 안 되는 까닭을 말하고, 쌍받침을 바르게 쓰는 방법을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u7-C3","difficulty":4,"kind":"essay","stem":"「낚시」를 「낙시」로 쓰면 안 되는 까닭을 말하고, 쌍받침을 바르게 쓰는 방법을 써 보세요.","answer_guide":{"answer":"예: 「낚시」의 받침은 ㄱ 두 개가 겹친 ㄲ이라서 ㄱ 하나만 쓰면 틀린 글자가 돼요. 받침 자리에 같은 자음자를 두 번 나란히 써요.","scoring_points":["받침이 ㄲ임을 말했는가","ㄱ 하나로 쓰면 틀림을 말했는가","바르게 쓰는 방법을 썼는가"]},"explanation":["받침 ㄲ.","틀린 까닭.","쓰는 방법."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L04_basic#1','kor',1,1,'u7','L04','g1_1_kor_u7_L04_basic','lesson_basic','K1-1-u7-C4',1,'mc','auto','그림에 알맞은 낱말은 어느 것인가요?',ARRAY['K1-1-u7-X05','K1-1-u7-X06']::text[],true,'{"seq":1,"concept":"K1-1-u7-C4","difficulty":1,"kind":"mc","stem":"그림에 알맞은 낱말은 어느 것인가요?","options":[{"t":"우산","correct":true},{"t":"우유","mis":"K1-1-u7-X05"},{"t":"모자","mis":"K1-1-u7-X06"}],"explanation":["그림은 비를 막는 우산이에요.","「우유」는 첫 글자만 같고, 모자는 그림과 달라요.","끝 글자까지 그림과 맞춰 봐요."],"asset":{"type":"scene","icon":"☂️"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림에 알맞은 낱말은 어느 것인가요?","options":[{"t":"장갑","correct":true},{"t":"장화","mis":"K1-1-u7-X05"},{"t":"양말","mis":"K1-1-u7-X06"}],"explanation":["그림은 손에 끼는 장갑이에요.","「장화」는 첫 글자만 같고, 양말은 그림과 달라요.","끝 글자까지 그림과 맞춰 봐요."],"asset":{"type":"scene","icon":"🧤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L04_basic#2','kor',1,1,'u7','L04','g1_1_kor_u7_L04_basic','lesson_basic','K1-1-u7-C4',1,'mc','auto','운동장 그림을 보고 답해요. 곰이 하고 있는 것은 어느 것인가요?',ARRAY['K1-1-u7-X05','K1-1-u7-X06']::text[],true,'{"seq":2,"concept":"K1-1-u7-C4","difficulty":1,"kind":"mc","stem":"운동장 그림을 보고 답해요. 곰이 하고 있는 것은 어느 것인가요?","options":[{"t":"줄넘기","correct":true},{"t":"줄다리기","mis":"K1-1-u7-X05"},{"t":"그네","mis":"K1-1-u7-X06"}],"explanation":["곰은 줄넘기를 하고 있어요.","「줄다리기」는 첫 글자만 같고, 그네는 다람쥐가 타요.","동물마다 하는 일을 하나씩 짚어요."],"asset":{"type":"scene","icon":"🐻🦊🐰🦁🐿️","text":"운동장에서 곰은 줄넘기를 하고, 여우는 자전거를 타요. 토끼는 공을 차고, 사자는 연을 날려요. 다람쥐는 그네를 타요."},"variant_rule":{"alt":[{"stem":"운동장 그림을 보고 답해요. 여우가 타고 있는 것은 어느 것인가요?","options":[{"t":"자전거","correct":true},{"t":"자동차","mis":"K1-1-u7-X05"},{"t":"그네","mis":"K1-1-u7-X06"}],"explanation":["여우는 자전거를 타고 있어요.","「자동차」는 첫 글자만 같고, 그네는 다람쥐가 타요.","동물마다 하는 일을 하나씩 짚어요."],"asset":{"type":"scene","icon":"🐻🦊🐰🦁🐿️","text":"운동장에서 곰은 줄넘기를 하고, 여우는 자전거를 타요. 토끼는 공을 차고, 사자는 연을 날려요. 다람쥐는 그네를 타요."}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
