INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L04_basic#5','kor',1,1,'u7','L04','g1_1_kor_u7_L04_basic','lesson_basic','K1-1-u7-C4',2,'match','auto','운동장 그림을 보고 동물과 하는 일을 이으세요.','{}'::text[],true,'{"seq":5,"concept":"K1-1-u7-C4","difficulty":2,"kind":"match","stem":"운동장 그림을 보고 동물과 하는 일을 이으세요.","pairs":[{"l":"곰","r":"줄넘기를 해요"},{"l":"토끼","r":"공을 차요"},{"l":"다람쥐","r":"그네를 타요"}],"mis":"K1-1-u7-X06","explanation":["곰은 줄넘기, 토끼는 공 차기, 다람쥐는 그네 타기를 해요.","동물마다 하는 일이 달라요.","그림에서 하나씩 짚어 봐요."],"asset":{"type":"scene","icon":"🐻🦊🐰🦁🐿️","text":"운동장에서 곰은 줄넘기를 하고, 여우는 자전거를 타요. 토끼는 공을 차고, 사자는 연을 날려요. 다람쥐는 그네를 타요."},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 운동장 그림을 보고 동물과 하는 일을 이으세요.","pairs":[{"l":"여우","r":"자전거를 타요"},{"l":"사자","r":"연을 날려요"},{"l":"곰","r":"줄넘기를 해요"}],"explanation":["여우는 자전거, 사자는 연, 곰은 줄넘기예요.","동물마다 하는 일이 달라요.","그림에서 하나씩 짚어 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L04_basic#6','kor',1,1,'u7','L04','g1_1_kor_u7_L04_basic','lesson_basic','K1-1-u7-C5',2,'blank','auto','「물을 (     )」에 들어갈 알맞은 말은 어느 것인가요?',ARRAY['K1-1-u7-X07']::text[],true,'{"seq":6,"concept":"K1-1-u7-C5","difficulty":2,"kind":"blank","stem":"「물을 (     )」에 들어갈 알맞은 말은 어느 것인가요?","options":[{"t":"마시다","correct":true},{"t":"날리다","mis":"K1-1-u7-X07"},{"t":"부르다","mis":"K1-1-u7-X07"}],"explanation":["「물을 마시다」가 어울리는 짝이에요.","「날리다」·「부르다」는 「물을」과 어울리지 않아요.","「무엇을」과 이어 소리 내어 읽어 보고 어색한지 살펴요."],"variant_rule":{"colloc":{"ask":"fill","kinds":["do"],"mis":{"do":"X07"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L04_basic#7','kor',1,1,'u7','L04','g1_1_kor_u7_L04_basic','lesson_basic','K1-1-u7-C4',2,'mc','auto','그림에 꼭 맞는 낱말을 찾는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u7-X05','K1-1-u7-X06']::text[],false,'{"seq":7,"concept":"K1-1-u7-C4","difficulty":2,"kind":"mc","stem":"그림에 꼭 맞는 낱말을 찾는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"그림을 자세히 보고, 낱말을 끝 글자까지 그림과 맞춰 봐요","correct":true},{"t":"첫 글자가 같으면 바로 골라요","mis":"K1-1-u7-X05"},{"t":"먼저 떠오른 낱말을 아무거나 써요","mis":"K1-1-u7-X06"}],"explanation":["그림을 자세히 보고 낱말 전체를 맞춰 봐야 해요.","첫 글자만 보거나 아무 낱말이나 쓰면 틀리기 쉬워요.","보기 → 떠올리기 → 맞춰 보기 차례로 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L04_basic#8','kor',1,1,'u7','L04','g1_1_kor_u7_L04_basic','lesson_basic','K1-1-u7-C4',2,'mc','auto','비 오는 날 발에 신는 것이에요. 알맞은 낱말은 어느 것인가요?',ARRAY['K1-1-u7-X05']::text[],true,'{"seq":8,"concept":"K1-1-u7-C4","difficulty":2,"kind":"mc","stem":"비 오는 날 발에 신는 것이에요. 알맞은 낱말은 어느 것인가요?","options":[{"t":"장화","correct":true},{"t":"장갑","mis":"K1-1-u7-X05"},{"t":"장난감","mis":"K1-1-u7-X05"}],"explanation":["비 오는 날 발에 신는 것은 장화예요.","「장갑」·「장난감」은 첫 글자만 같아요.","끝 글자까지 그림과 맞춰 봐요."],"asset":{"type":"scene","icon":"👢🌧️"},"variant_rule":{"alt":[{"stem":"아침에 컵에 따라 마시는 하얀 것이에요. 알맞은 낱말은 어느 것인가요?","options":[{"t":"우유","correct":true},{"t":"우산","mis":"K1-1-u7-X05"},{"t":"우물","mis":"K1-1-u7-X05"}],"explanation":["컵에 따라 마시는 하얀 것은 우유예요.","「우산」·「우물」은 첫 글자만 같아요.","끝 글자까지 그림과 맞춰 봐요."],"asset":{"type":"scene","icon":"🥛"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L04_basic#9','kor',1,1,'u7','L04','g1_1_kor_u7_L04_basic','lesson_basic','K1-1-u7-C5',2,'ox','auto','문장의 빈칸에는 그림과 앞뒤 말에 어울리는 낱말을 넣어야 해요.',ARRAY['K1-1-u7-X06']::text[],false,'{"seq":9,"concept":"K1-1-u7-C5","difficulty":2,"kind":"ox","stem":"문장의 빈칸에는 그림과 앞뒤 말에 어울리는 낱말을 넣어야 해요.","answer":"O","reason_options":[{"t":"그림과 앞뒤 말에 어울려야 뜻이 통하는 문장이 되니까","correct":true},{"t":"빈칸에는 아무 낱말이나 넣어도 되니까","mis":"K1-1-u7-X06"}],"mis":"K1-1-u7-X06","explanation":["빈칸에는 그림과 앞뒤 말에 어울리는 낱말을 넣어요.","아무 낱말이나 넣으면 뜻이 통하지 않아요.","넣은 뒤 소리 내어 읽어 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
