INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L04_challenge#1','kor',1,1,'u7','L04','g1_1_kor_u7_L04_challenge','lesson_challenge','K1-1-u7-C4',2,'mc','auto','운동장 그림에 나오지 않는 것은 어느 것인가요?',ARRAY['K1-1-u7-X06']::text[],false,'{"seq":1,"concept":"K1-1-u7-C4","difficulty":2,"kind":"mc","stem":"운동장 그림에 나오지 않는 것은 어느 것인가요?","options":[{"t":"훌라후프","correct":true},{"t":"자전거","mis":"K1-1-u7-X06"},{"t":"연","mis":"K1-1-u7-X06"}],"explanation":["운동장 그림에 훌라후프는 없어요.","자전거는 여우가, 연은 사자가 가지고 있어요.","그림을 끝까지 살펴요."],"asset":{"type":"scene","icon":"🐻🦊🐰🦁🐿️","text":"운동장에서 곰은 줄넘기를 하고, 여우는 자전거를 타요. 토끼는 공을 차고, 사자는 연을 날려요. 다람쥐는 그네를 타요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L04_challenge#2','kor',1,1,'u7','L04','g1_1_kor_u7_L04_challenge','lesson_challenge','K1-1-u7-C5',2,'blank','auto','「(     ) 날리다」에 들어갈 알맞은 말은 어느 것인가요?',ARRAY['K1-1-u7-X07']::text[],true,'{"seq":2,"concept":"K1-1-u7-C5","difficulty":2,"kind":"blank","stem":"「(     ) 날리다」에 들어갈 알맞은 말은 어느 것인가요?","options":[{"t":"연을","correct":true},{"t":"물을","mis":"K1-1-u7-X07"},{"t":"노래를","mis":"K1-1-u7-X07"}],"explanation":["「연을 날리다」가 어울리는 짝이에요.","「물을」·「노래를」은 「날리다」와 어울리지 않아요.","「무엇을」과 이어 소리 내어 읽어 보고 어색한지 살펴요."],"variant_rule":{"colloc":{"ask":"back","kinds":["do"],"mis":{"do":"X07"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
