INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L04_challenge#4','kor',1,1,'u7','L04','g1_1_kor_u7_L04_challenge','lesson_challenge','K1-1-u7-C4',3,'mc','auto','「장갑」과 「장화」를 가려 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u7-X05']::text[],false,'{"seq":4,"concept":"K1-1-u7-C4","difficulty":3,"kind":"mc","stem":"「장갑」과 「장화」를 가려 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"손에 끼면 장갑, 발에 신으면 장화예요","correct":true},{"t":"첫 글자가 같으니 아무거나 써요","mis":"K1-1-u7-X05"},{"t":"색깔로 가려요","mis":"K1-1-u7-X05"}],"explanation":["장갑은 손에 끼고, 장화는 발에 신어요.","첫 글자만 같다고 같은 물건이 아니에요.","어디에 쓰는 물건인지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
