INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L04_challenge#7','kor',1,1,'u7','L04','g1_1_kor_u7_L04_challenge','lesson_challenge','K1-1-u7-C4',3,'ox','auto','「우산」과 「우유」는 첫 글자가 같으니 그림을 보고 아무것이나 골라도 돼요.',ARRAY['K1-1-u7-X05']::text[],false,'{"seq":7,"concept":"K1-1-u7-C4","difficulty":3,"kind":"ox","stem":"「우산」과 「우유」는 첫 글자가 같으니 그림을 보고 아무것이나 골라도 돼요.","answer":"X","reason_options":[{"t":"끝 글자까지 그림과 맞춰야 알맞은 낱말을 찾을 수 있으니까","correct":true},{"t":"첫 글자만 같으면 같은 물건이니까","mis":"K1-1-u7-X05"}],"mis":"K1-1-u7-X05","explanation":["「우산」과 「우유」는 다른 물건이에요.","첫 글자만 보면 틀리기 쉬워요.","끝 글자까지 그림과 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L04_challenge#8','kor',1,1,'u7','L04','g1_1_kor_u7_L04_challenge','lesson_challenge','K1-1-u7-C5',4,'mc','auto','운동장 그림에 알맞은 문장만 모은 것은 어느 것인가요?',ARRAY['K1-1-u7-X06']::text[],false,'{"seq":8,"concept":"K1-1-u7-C5","difficulty":4,"kind":"mc","stem":"운동장 그림에 알맞은 문장만 모은 것은 어느 것인가요?","options":[{"t":"곰이 줄넘기를 해요. · 다람쥐가 그네를 타요.","correct":true},{"t":"곰이 줄넘기를 해요. · 사자가 공을 차요.","mis":"K1-1-u7-X06"},{"t":"여우가 연을 날려요. · 다람쥐가 그네를 타요.","mis":"K1-1-u7-X06"}],"explanation":["곰은 줄넘기, 다람쥐는 그네예요.","공을 차는 것은 토끼, 연을 날리는 것은 사자예요.","두 문장 모두 그림과 맞는지 살펴요."],"asset":{"type":"scene","icon":"🐻🦊🐰🦁🐿️","text":"운동장에서 곰은 줄넘기를 하고, 여우는 자전거를 타요. 토끼는 공을 차고, 사자는 연을 날려요. 다람쥐는 그네를 타요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L04_challenge#9','kor',1,1,'u7','L04','g1_1_kor_u7_L04_challenge','lesson_challenge','K1-1-u7-C4',4,'essay','teacher','운동장 그림에서 동물 하나를 골라 알맞은 낱말을 넣어 문장을 쓰고, 그 낱말을 고른 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u7-C4","difficulty":4,"kind":"essay","stem":"운동장 그림에서 동물 하나를 골라 알맞은 낱말을 넣어 문장을 쓰고, 그 낱말을 고른 까닭을 써 보세요.","answer_guide":{"answer":"예: 여우가 자전거를 타요. — 그림에서 여우가 자전거 위에 앉아 있으니까요.","scoring_points":["그림에 나온 동물로 썼는가","그림에 알맞은 낱말을 넣었는가","고른 까닭을 그림에서 찾아 썼는가"]},"explanation":["동물 고르기.","알맞은 낱말.","까닭."],"asset":{"type":"scene","icon":"🐻🦊🐰🦁🐿️","text":"운동장에서 곰은 줄넘기를 하고, 여우는 자전거를 타요. 토끼는 공을 차고, 사자는 연을 날려요. 다람쥐는 그네를 타요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L04_challenge#10','kor',1,1,'u7','L04','g1_1_kor_u7_L04_challenge','lesson_challenge','K1-1-u7-C5',4,'essay','teacher','「누가 + 무엇을 + 먹어요」 꼴로 알맞은 낱말을 넣어 문장을 두 가지 만들어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u7-C5","difficulty":4,"kind":"essay","stem":"「누가 + 무엇을 + 먹어요」 꼴로 알맞은 낱말을 넣어 문장을 두 가지 만들어 보세요.","answer_guide":{"answer":"예: 토끼가 당근을 먹어요. / 아기가 사과를 먹어요.","scoring_points":["누가에 알맞은 낱말을 넣었는가","「먹어요」와 어울리는 무엇을을 넣었는가","두 문장이 모두 뜻이 통하는가"]},"explanation":["누가.","먹어요와 어울리는 무엇을.","뜻이 통하는 두 문장."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
