INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L06_basic#2','kor',1,1,'u7','L06','g1_1_kor_u7_L06_basic','lesson_basic','K1-1-u7-C6',1,'mc','auto','「무엇은 무엇입니다」로 바르게 말한 것은 어느 것인가요?',ARRAY['K1-1-u7-X08','K1-1-u7-X09']::text[],true,'{"seq":2,"concept":"K1-1-u7-C6","difficulty":1,"kind":"mc","stem":"「무엇은 무엇입니다」로 바르게 말한 것은 어느 것인가요?","options":[{"t":"오리는 동물입니다.","correct":true},{"t":"오리는 과일입니다.","mis":"K1-1-u7-X08"},{"t":"오리는 물을 입니다.","mis":"K1-1-u7-X09"}],"explanation":["오리는 동물 무리에 들어요.","오리는 과일이 아니고, 「물을 입니다」는 두 틀이 섞였어요.","앞 낱말이 뒤 무리에 드는지 살펴요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 「무엇은 무엇입니다」로 바르게 말한 것은 어느 것인가요?","options":[{"t":"당근은 채소입니다.","correct":true},{"t":"당근은 동물입니다.","mis":"K1-1-u7-X08"},{"t":"당근은 토끼를 입니다.","mis":"K1-1-u7-X09"}],"explanation":["당근은 채소 무리에 들어요.","당근은 동물이 아니고, 「토끼를 입니다」는 두 틀이 섞였어요.","앞 낱말이 뒤 무리에 드는지 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
