INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L06_basic#5','kor',1,1,'u7','L06','g1_1_kor_u7_L06_basic','lesson_basic','K1-1-u7-C6',2,'match','auto','낱말과 어울리는 무리를 이으세요.','{}'::text[],true,'{"seq":5,"concept":"K1-1-u7-C6","difficulty":2,"kind":"match","stem":"낱말과 어울리는 무리를 이으세요.","pairs":[{"l":"사과","r":"과일"},{"l":"당근","r":"채소"},{"l":"장미","r":"꽃"},{"l":"오리","r":"동물"}],"mis":"K1-1-u7-X08","explanation":["사과는 과일, 당근은 채소, 장미는 꽃, 오리는 동물이에요.","낱말마다 들어가는 무리가 달라요.","「○○는 □□입니다」로 말해 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 어울리는 무리를 이으세요.","pairs":[{"l":"포도","r":"과일"},{"l":"오이","r":"채소"},{"l":"해바라기","r":"꽃"},{"l":"사자","r":"동물"}],"explanation":["포도는 과일, 오이는 채소, 해바라기는 꽃, 사자는 동물이에요.","낱말마다 들어가는 무리가 달라요.","「○○는 □□입니다」로 말해 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L06_basic#6','kor',1,1,'u7','L06','g1_1_kor_u7_L06_basic','lesson_basic','K1-1-u7-C6',2,'mc','auto','「무엇은 어떠합니다」로 말한 문장은 어느 것인가요?',ARRAY['K1-1-u7-X09']::text[],true,'{"seq":6,"concept":"K1-1-u7-C6","difficulty":2,"kind":"mc","stem":"「무엇은 어떠합니다」로 말한 문장은 어느 것인가요?","options":[{"t":"얼음은 차갑습니다.","correct":true},{"t":"얼음은 물건입니다.","mis":"K1-1-u7-X09"},{"t":"얼음을 먹습니다.","mis":"K1-1-u7-X09"}],"explanation":["「얼음은 차갑습니다」는 얼음이 어떠한지 말해요.","다른 두 문장은 무리를 말하거나 하는 일을 말해요.","「어떠한가?」를 말하는 문장을 찾아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 「무엇은 어떠합니다」로 말한 문장은 어느 것인가요?","options":[{"t":"솜은 부드럽습니다.","correct":true},{"t":"솜은 물건입니다.","mis":"K1-1-u7-X09"},{"t":"솜을 만집니다.","mis":"K1-1-u7-X09"}],"explanation":["「솜은 부드럽습니다」는 솜이 어떠한지 말해요.","다른 두 문장은 무리를 말하거나 하는 일을 말해요.","「어떠한가?」를 말하는 문장을 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L06_basic#7','kor',1,1,'u7','L06','g1_1_kor_u7_L06_basic','lesson_basic','K1-1-u7-C7',2,'ox','auto','「다람쥐가 먹습니다.」만으로는 다람쥐가 무엇을 먹는지 알 수 없어요.',ARRAY['K1-1-u7-X10']::text[],false,'{"seq":7,"concept":"K1-1-u7-C7","difficulty":2,"kind":"ox","stem":"「다람쥐가 먹습니다.」만으로는 다람쥐가 무엇을 먹는지 알 수 없어요.","answer":"O","reason_options":[{"t":"「무엇을」 조각이 빠졌으니까","correct":true},{"t":"「누가」만 있으면 다 알 수 있으니까","mis":"K1-1-u7-X10"}],"mis":"K1-1-u7-X10","explanation":["「무엇을」이 없어 무엇을 먹는지 몰라요.","「다람쥐가 도토리를 먹습니다.」처럼 써요.","「무엇을?」 하고 되물어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
