INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L06_basic#9','kor',1,1,'u7','L06','g1_1_kor_u7_L06_basic','lesson_basic','K1-1-u7-C6',2,'mc','auto','오리를 보고 「무엇은 어떠합니다」로 말한 것은 어느 것인가요?',ARRAY['K1-1-u7-X08','K1-1-u7-X09']::text[],true,'{"seq":9,"concept":"K1-1-u7-C6","difficulty":2,"kind":"mc","stem":"오리를 보고 「무엇은 어떠합니다」로 말한 것은 어느 것인가요?","options":[{"t":"오리는 하얗습니다.","correct":true},{"t":"오리는 과일입니다.","mis":"K1-1-u7-X08"},{"t":"오리를 하얗습니다.","mis":"K1-1-u7-X09"}],"explanation":["「오리는 하얗습니다」는 오리가 어떠한지 말해요.","오리는 과일이 아니고, 「오리를」은 틀에 맞지 않아요.","「오리는 어떠한가?」 생각해요."],"asset":{"type":"scene","icon":"🦆"},"variant_rule":{"alt":[{"stem":"기린을 보고 「무엇은 어떠합니다」로 말한 것은 어느 것인가요?","options":[{"t":"기린은 목이 깁니다.","correct":true},{"t":"기린은 채소입니다.","mis":"K1-1-u7-X08"},{"t":"기린을 목이 깁니다.","mis":"K1-1-u7-X09"}],"explanation":["「기린은 목이 깁니다」는 기린이 어떠한지 말해요.","기린은 채소가 아니고, 「기린을」은 틀에 맞지 않아요.","「기린은 어떠한가?」 생각해요."],"asset":{"type":"scene","icon":"🦒"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
