INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L06_challenge#7','kor',1,1,'u7','L06','g1_1_kor_u7_L06_challenge','lesson_challenge','K1-1-u7-C6',3,'ox','auto','「무엇은 무엇입니다」로 말할 때는 앞 낱말이 뒤 무리에 들어가는지 살펴야 해요.',ARRAY['K1-1-u7-X08']::text[],false,'{"seq":7,"concept":"K1-1-u7-C6","difficulty":3,"kind":"ox","stem":"「무엇은 무엇입니다」로 말할 때는 앞 낱말이 뒤 무리에 들어가는지 살펴야 해요.","answer":"O","reason_options":[{"t":"복숭아가 과일 무리에 들어가야 「복숭아는 과일입니다」가 맞으니까","correct":true},{"t":"아무 무리나 붙여도 문장이 되니까","mis":"K1-1-u7-X08"}],"mis":"K1-1-u7-X08","explanation":["앞 낱말이 뒤 무리에 들어가야 뜻이 맞아요.","아무 무리나 붙이면 틀린 문장이 돼요.","「○○는 □□ 가운데 하나인가?」 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L06_challenge#8','kor',1,1,'u7','L06','g1_1_kor_u7_L06_challenge','lesson_challenge','K1-1-u7-C7',4,'mc','auto','무대 그림에 알맞은 문장만 모은 것은 어느 것인가요?',ARRAY['K1-1-u7-X07','K1-1-u7-X06']::text[],false,'{"seq":8,"concept":"K1-1-u7-C7","difficulty":4,"kind":"mc","stem":"무대 그림에 알맞은 문장만 모은 것은 어느 것인가요?","options":[{"t":"호랑이가 춤을 춥니다. · 곰이 노래를 부릅니다.","correct":true},{"t":"호랑이가 노래를 춥니다. · 곰이 노래를 부릅니다.","mis":"K1-1-u7-X07"},{"t":"원숭이가 춤을 춥니다. · 곰이 노래를 부릅니다.","mis":"K1-1-u7-X06"}],"explanation":["호랑이는 춤을 추고, 곰은 노래를 불러요.","「노래를 춥니다」는 어울리지 않고, 춤추는 것은 원숭이가 아니에요.","두 문장 모두 그림과 맞는지 살펴요."],"asset":{"type":"scene","icon":"🐯💃🐻🎤🐵🎹","text":"무대에서 호랑이는 춤을 추고, 곰은 노래를 부르고, 원숭이는 피아노를 쳐요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L06_challenge#9','kor',1,1,'u7','L06','g1_1_kor_u7_L06_challenge','lesson_challenge','K1-1-u7-C6',4,'essay','teacher','그림을 보고 「무엇은 무엇입니다」 문장 하나와 「무엇은 어떠합니다」 문장 하나를 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u7-C6","difficulty":4,"kind":"essay","stem":"그림을 보고 「무엇은 무엇입니다」 문장 하나와 「무엇은 어떠합니다」 문장 하나를 써 보세요.","answer_guide":{"answer":"예: 복숭아는 과일입니다. / 오리는 하얗습니다.","scoring_points":["「무엇은 무엇입니다」 틀로 썼는가","「무엇은 어떠합니다」 틀로 썼는가","두 틀을 섞지 않았는가"]},"explanation":["무엇은 무엇입니다.","무엇은 어떠합니다.","틀 섞지 않기."],"asset":{"type":"scene","icon":"🍑🌹🦆"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L06_challenge#10','kor',1,1,'u7','L06','g1_1_kor_u7_L06_challenge','lesson_challenge','K1-1-u7-C7',4,'essay','teacher','무대 그림에서 동물 하나를 골라 「누가 무엇을 합니다」로 쓰고, 「무엇을」을 빼면 어떻게 되는지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u7-C7","difficulty":4,"kind":"essay","stem":"무대 그림에서 동물 하나를 골라 「누가 무엇을 합니다」로 쓰고, 「무엇을」을 빼면 어떻게 되는지 써 보세요.","answer_guide":{"answer":"예: 원숭이가 피아노를 칩니다. — 「피아노를」을 빼면 무엇을 치는지 알 수 없어요.","scoring_points":["그림에 맞는 문장을 썼는가","누가·무엇을·어찌하다가 다 있는가","무엇을을 빼면 생기는 일을 썼는가"]},"explanation":["그림에 맞는 문장.","세 조각.","무엇을을 빼면."],"asset":{"type":"scene","icon":"🐯💃🐻🎤🐵🎹","text":"무대에서 호랑이는 춤을 추고, 곰은 노래를 부르고, 원숭이는 피아노를 쳐요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L09_basic#1','kor',1,1,'u7','L09','g1_1_kor_u7_L09_basic','lesson_basic','K1-1-u7-C8',1,'mc','auto','이야기를 읽고 답해요. 보리는 어디에서 그림책을 펼쳤나요?',ARRAY['K1-1-u7-X12']::text[],false,'{"seq":1,"concept":"K1-1-u7-C8","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해요. 보리는 어디에서 그림책을 펼쳤나요?","options":[{"t":"도서관","correct":true},{"t":"바다","mis":"K1-1-u7-X12"},{"t":"기차","mis":"K1-1-u7-X12"}],"explanation":["보리는 도서관에서 그림책을 펼쳤어요.","바다와 기차는 책 속에서 나온 곳이에요.","이야기 첫 문장을 다시 읽어요."],"asset":{"type":"passage","lines":["도서관에서 고양이 보리가 그림책을 펼쳤어요.","책장을 넘기자 보리는 책 속 바다에 풍덩 빠졌어요.","보리는 파란 바다에서 헤엄을 쳤어요.","다음 장에는 하얀 눈 산이 나왔어요. 눈보라가 휘잉 불었어요.","보리는 칙칙폭폭 기차를 타고 눈 산을 빠져나왔어요.","기차에서 내린 보리는 넓은 들판에서 피리를 불었어요.","책을 덮자 보리는 다시 도서관 의자 위에 앉아 있었어요."],"title":"책 속으로 떠난 고양이 보리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L09_basic#2','kor',1,1,'u7','L09','g1_1_kor_u7_L09_basic','lesson_basic','K1-1-u7-C8',1,'blank','auto','이야기에 알맞게 빈칸을 채워요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L09_basic#3','kor',1,1,'u7','L09','g1_1_kor_u7_L09_basic','lesson_basic','K1-1-u7-C8',1,'mc','auto','이야기를 읽고 답해요. 들판에서 보리가 한 일은 무엇인가요?',ARRAY['K1-1-u7-X12']::text[],false,'{"seq":3,"concept":"K1-1-u7-C8","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해요. 들판에서 보리가 한 일은 무엇인가요?","options":[{"t":"피리를 불었어요","correct":true},{"t":"헤엄을 쳤어요","mis":"K1-1-u7-X12"},{"t":"그림책을 덮었어요","mis":"K1-1-u7-X12"}],"explanation":["보리는 들판에서 피리를 불었어요.","헤엄은 바다에서, 책을 덮은 것은 도서관에서예요.","장소와 한 일을 짝 지어요."],"asset":{"type":"passage","lines":["도서관에서 고양이 보리가 그림책을 펼쳤어요.","책장을 넘기자 보리는 책 속 바다에 풍덩 빠졌어요.","보리는 파란 바다에서 헤엄을 쳤어요.","다음 장에는 하얀 눈 산이 나왔어요. 눈보라가 휘잉 불었어요.","보리는 칙칙폭폭 기차를 타고 눈 산을 빠져나왔어요.","기차에서 내린 보리는 넓은 들판에서 피리를 불었어요.","책을 덮자 보리는 다시 도서관 의자 위에 앉아 있었어요."],"title":"책 속으로 떠난 고양이 보리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
