INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L09_basic#5','kor',1,1,'u7','L09','g1_1_kor_u7_L09_basic','lesson_basic','K1-1-u7-C8',2,'match','auto','낱말과 알맞은 뜻을 이으세요.','{}'::text[],true,'{"seq":5,"concept":"K1-1-u7-C8","difficulty":2,"kind":"match","stem":"낱말과 알맞은 뜻을 이으세요.","pairs":[{"l":"눈보라","r":"바람에 휘몰아쳐 날리는 눈"},{"l":"들판","r":"넓고 평평하게 펼쳐진 땅"},{"l":"헤엄","r":"물속에서 팔다리를 움직여 나아가는 일"}],"mis":"K1-1-u7-X13","explanation":["낱말 뜻을 알면 장면을 잘 떠올릴 수 있어요.","글자 모양만 보고 뜻을 짐작하면 틀리기 쉬워요.","앞뒤 문장을 읽고 뜻을 짐작해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 알맞은 뜻을 이으세요.","pairs":[{"l":"피리","r":"입으로 불어 소리를 내는 악기"},{"l":"그림책","r":"그림이 많이 들어 있는 책"},{"l":"기차","r":"여러 칸을 이어 철길 위를 달리는 탈것"}],"explanation":["낱말 뜻을 알면 장면을 잘 떠올릴 수 있어요.","글자 모양만 보고 뜻을 짐작하면 틀리기 쉬워요.","앞뒤 문장을 읽고 뜻을 짐작해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L09_basic#6','kor',1,1,'u7','L09','g1_1_kor_u7_L09_basic','lesson_basic','K1-1-u7-C8',2,'mc','auto','「눈보라」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u7-X13']::text[],false,'{"seq":6,"concept":"K1-1-u7-C8","difficulty":2,"kind":"mc","stem":"「눈보라」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"바람에 휘몰아쳐 날리는 눈","correct":true},{"t":"보라색으로 내리는 눈","mis":"K1-1-u7-X13"},{"t":"눈을 감고 보는 것","mis":"K1-1-u7-X13"}],"explanation":["눈보라는 바람에 휘몰아쳐 날리는 눈이에요.","「보라」라는 글자만 보고 보라색이나 「보다」로 짐작하면 안 돼요.","「휘잉 불었어요」와 함께 장면을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
