INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L09_basic#8','kor',1,1,'u7','L09','g1_1_kor_u7_L09_basic','lesson_basic','K1-1-u7-C8',2,'ox','auto','이야기에서 보리는 눈 산에서 눈사람을 만들었어요.',ARRAY['K1-1-u7-X12']::text[],false,'{"seq":8,"concept":"K1-1-u7-C8","difficulty":2,"kind":"ox","stem":"이야기에서 보리는 눈 산에서 눈사람을 만들었어요.","answer":"X","reason_options":[{"t":"이야기에는 눈보라가 불었다고만 나오니까","correct":true},{"t":"눈 산이니까 눈사람을 만들었을 거니까","mis":"K1-1-u7-X12"}],"mis":"K1-1-u7-X12","explanation":["이야기에 눈사람을 만든 일은 나오지 않아요.","짐작한 일을 이야기에 나온 일처럼 말하면 안 돼요.","이야기에서 그 장면을 찾아 확인해요."],"asset":{"type":"passage","lines":["도서관에서 고양이 보리가 그림책을 펼쳤어요.","책장을 넘기자 보리는 책 속 바다에 풍덩 빠졌어요.","보리는 파란 바다에서 헤엄을 쳤어요.","다음 장에는 하얀 눈 산이 나왔어요. 눈보라가 휘잉 불었어요.","보리는 칙칙폭폭 기차를 타고 눈 산을 빠져나왔어요.","기차에서 내린 보리는 넓은 들판에서 피리를 불었어요.","책을 덮자 보리는 다시 도서관 의자 위에 앉아 있었어요."],"title":"책 속으로 떠난 고양이 보리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L09_basic#9','kor',1,1,'u7','L09','g1_1_kor_u7_L09_basic','lesson_basic','K1-1-u7-C8',2,'mc','auto','이야기의 한 장면을 문장으로 바르게 만든 것은 어느 것인가요?',ARRAY['K1-1-u7-X07','K1-1-u7-X12']::text[],false,'{"seq":9,"concept":"K1-1-u7-C8","difficulty":2,"kind":"mc","stem":"이야기의 한 장면을 문장으로 바르게 만든 것은 어느 것인가요?","options":[{"t":"보리가 바다에서 헤엄을 쳤어요.","correct":true},{"t":"보리가 바다에서 피리를 쳤어요.","mis":"K1-1-u7-X07"},{"t":"보리가 도서관에서 기차를 탔어요.","mis":"K1-1-u7-X12"}],"explanation":["보리는 바다에서 헤엄을 쳤어요.","「피리를 쳤어요」는 어울리지 않고, 도서관에서 기차를 탄 일은 없어요.","누가·어디에서·무엇을 했는지 이야기에서 찾아요."],"asset":{"type":"passage","lines":["도서관에서 고양이 보리가 그림책을 펼쳤어요.","책장을 넘기자 보리는 책 속 바다에 풍덩 빠졌어요.","보리는 파란 바다에서 헤엄을 쳤어요.","다음 장에는 하얀 눈 산이 나왔어요. 눈보라가 휘잉 불었어요.","보리는 칙칙폭폭 기차를 타고 눈 산을 빠져나왔어요.","기차에서 내린 보리는 넓은 들판에서 피리를 불었어요.","책을 덮자 보리는 다시 도서관 의자 위에 앉아 있었어요."],"title":"책 속으로 떠난 고양이 보리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L09_basic#10','kor',1,1,'u7','L09','g1_1_kor_u7_L09_basic','lesson_basic','K1-1-u7-C8',3,'error','auto','로아가 이야기를 읽고 이렇게 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L09_challenge#1','kor',1,1,'u7','L09','g1_1_kor_u7_L09_challenge','lesson_challenge','K1-1-u7-C8',2,'mc','auto','이야기를 읽고 답해요. 책을 덮자 보리는 어디에 있었나요?',ARRAY['K1-1-u7-X12']::text[],false,'{"seq":1,"concept":"K1-1-u7-C8","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해요. 책을 덮자 보리는 어디에 있었나요?","options":[{"t":"도서관 의자 위","correct":true},{"t":"기차 안","mis":"K1-1-u7-X12"},{"t":"바닷속","mis":"K1-1-u7-X12"}],"explanation":["책을 덮자 보리는 다시 도서관 의자 위에 있었어요.","기차와 바다는 책 속 장면이에요.","이야기 끝 문장을 다시 읽어요."],"asset":{"type":"passage","lines":["도서관에서 고양이 보리가 그림책을 펼쳤어요.","책장을 넘기자 보리는 책 속 바다에 풍덩 빠졌어요.","보리는 파란 바다에서 헤엄을 쳤어요.","다음 장에는 하얀 눈 산이 나왔어요. 눈보라가 휘잉 불었어요.","보리는 칙칙폭폭 기차를 타고 눈 산을 빠져나왔어요.","기차에서 내린 보리는 넓은 들판에서 피리를 불었어요.","책을 덮자 보리는 다시 도서관 의자 위에 앉아 있었어요."],"title":"책 속으로 떠난 고양이 보리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L09_challenge#2','kor',1,1,'u7','L09','g1_1_kor_u7_L09_challenge','lesson_challenge','K1-1-u7-C8',2,'mc','auto','이야기에서 보리가 간 곳을 차례대로 놓은 것은 어느 것인가요?',ARRAY['K1-1-u7-X12']::text[],false,'{"seq":2,"concept":"K1-1-u7-C8","difficulty":2,"kind":"mc","stem":"이야기에서 보리가 간 곳을 차례대로 놓은 것은 어느 것인가요?","options":[{"t":"바다 → 눈 산 → 들판","correct":true},{"t":"들판 → 바다 → 눈 산","mis":"K1-1-u7-X12"},{"t":"눈 산 → 바다 → 들판","mis":"K1-1-u7-X12"}],"explanation":["바다에서 헤엄치고, 눈 산을 지나, 들판에서 피리를 불었어요.","차례를 바꾸면 이야기가 달라져요.","이야기를 처음부터 차례로 짚어요."],"asset":{"type":"passage","lines":["도서관에서 고양이 보리가 그림책을 펼쳤어요.","책장을 넘기자 보리는 책 속 바다에 풍덩 빠졌어요.","보리는 파란 바다에서 헤엄을 쳤어요.","다음 장에는 하얀 눈 산이 나왔어요. 눈보라가 휘잉 불었어요.","보리는 칙칙폭폭 기차를 타고 눈 산을 빠져나왔어요.","기차에서 내린 보리는 넓은 들판에서 피리를 불었어요.","책을 덮자 보리는 다시 도서관 의자 위에 앉아 있었어요."],"title":"책 속으로 떠난 고양이 보리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
