INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L09_challenge#4','kor',1,1,'u7','L09','g1_1_kor_u7_L09_challenge','lesson_challenge','K1-1-u7-C8',3,'mc','auto','보리가 기차를 탄 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u7-X12']::text[],false,'{"seq":4,"concept":"K1-1-u7-C8","difficulty":3,"kind":"mc","stem":"보리가 기차를 탄 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"눈보라가 부는 눈 산을 빠져나오려고","correct":true},{"t":"바다에서 헤엄을 치려고","mis":"K1-1-u7-X12"},{"t":"도서관에 책을 빌리러 가려고","mis":"K1-1-u7-X12"}],"explanation":["보리는 기차를 타고 눈 산을 빠져나왔어요.","헤엄은 그 전에, 도서관은 책을 덮은 뒤의 일이에요.","앞뒤 문장을 이어 까닭을 찾아요."],"asset":{"type":"passage","lines":["도서관에서 고양이 보리가 그림책을 펼쳤어요.","책장을 넘기자 보리는 책 속 바다에 풍덩 빠졌어요.","보리는 파란 바다에서 헤엄을 쳤어요.","다음 장에는 하얀 눈 산이 나왔어요. 눈보라가 휘잉 불었어요.","보리는 칙칙폭폭 기차를 타고 눈 산을 빠져나왔어요.","기차에서 내린 보리는 넓은 들판에서 피리를 불었어요.","책을 덮자 보리는 다시 도서관 의자 위에 앉아 있었어요."],"title":"책 속으로 떠난 고양이 보리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
