INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L09_challenge#6','kor',1,1,'u7','L09','g1_1_kor_u7_L09_challenge','lesson_challenge','K1-1-u7-C8',3,'mc','auto','「들판」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u7-X13']::text[],false,'{"seq":6,"concept":"K1-1-u7-C8","difficulty":3,"kind":"mc","stem":"「들판」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"넓고 평평하게 펼쳐진 땅","correct":true},{"t":"들고 다니는 판자","mis":"K1-1-u7-X13"},{"t":"들어가는 문","mis":"K1-1-u7-X13"}],"explanation":["들판은 넓고 평평하게 펼쳐진 땅이에요.","「들」이라는 글자만 보고 「들다」로 짐작하면 안 돼요.","「넓은 들판에서 피리를 불었어요」를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L09_challenge#7','kor',1,1,'u7','L09','g1_1_kor_u7_L09_challenge','lesson_challenge','K1-1-u7-C8',3,'ox','auto','이야기 장면을 문장으로 만들 때는 누가, 어디에서, 무엇을 했는지 이야기에서 찾아 써요.',ARRAY['K1-1-u7-X12']::text[],false,'{"seq":7,"concept":"K1-1-u7-C8","difficulty":3,"kind":"ox","stem":"이야기 장면을 문장으로 만들 때는 누가, 어디에서, 무엇을 했는지 이야기에서 찾아 써요.","answer":"O","reason_options":[{"t":"이야기에 나온 일을 알맞은 낱말로 써야 뜻이 맞으니까","correct":true},{"t":"이야기에 없는 일을 마음대로 써도 되니까","mis":"K1-1-u7-X12"}],"mis":"K1-1-u7-X12","explanation":["이야기에서 찾은 내용으로 문장을 만들어요.","없는 일을 쓰면 다른 이야기가 돼요.","누가·어디에서·무엇을 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L09_challenge#8','kor',1,1,'u7','L09','g1_1_kor_u7_L09_challenge','lesson_challenge','K1-1-u7-C8',4,'mc','auto','이야기에 알맞은 문장만 모은 것은 어느 것인가요?',ARRAY['K1-1-u7-X12','K1-1-u7-X07']::text[],false,'{"seq":8,"concept":"K1-1-u7-C8","difficulty":4,"kind":"mc","stem":"이야기에 알맞은 문장만 모은 것은 어느 것인가요?","options":[{"t":"보리가 그림책을 펼쳤어요. · 보리가 피리를 불었어요.","correct":true},{"t":"보리가 그림책을 찢었어요. · 보리가 피리를 불었어요.","mis":"K1-1-u7-X12"},{"t":"보리가 그림책을 펼쳤어요. · 보리가 피리를 쳤어요.","mis":"K1-1-u7-X07"}],"explanation":["보리는 그림책을 펼치고, 들판에서 피리를 불었어요.","그림책을 찢은 일은 없고, 「피리를 쳤어요」는 어울리지 않아요.","두 문장을 모두 이야기와 맞춰 봐요."],"asset":{"type":"passage","lines":["도서관에서 고양이 보리가 그림책을 펼쳤어요.","책장을 넘기자 보리는 책 속 바다에 풍덩 빠졌어요.","보리는 파란 바다에서 헤엄을 쳤어요.","다음 장에는 하얀 눈 산이 나왔어요. 눈보라가 휘잉 불었어요.","보리는 칙칙폭폭 기차를 타고 눈 산을 빠져나왔어요.","기차에서 내린 보리는 넓은 들판에서 피리를 불었어요.","책을 덮자 보리는 다시 도서관 의자 위에 앉아 있었어요."],"title":"책 속으로 떠난 고양이 보리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L09_challenge#9','kor',1,1,'u7','L09','g1_1_kor_u7_L09_challenge','lesson_challenge','K1-1-u7-C8',4,'essay','teacher','이야기에서 가장 재미있는 장면을 하나 골라 「누가 어디에서 무엇을 했어요」 꼴의 문장으로 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u7-C8","difficulty":4,"kind":"essay","stem":"이야기에서 가장 재미있는 장면을 하나 골라 「누가 어디에서 무엇을 했어요」 꼴의 문장으로 써 보세요.","answer_guide":{"answer":"예: 보리가 파란 바다에서 헤엄을 쳤어요.","scoring_points":["이야기에 나온 장면을 골랐는가","누가·어디에서·무엇을이 다 들어갔는가","알맞은 낱말로 뜻이 통하게 썼는가"]},"explanation":["이야기 장면.","세 조각.","알맞은 낱말."],"asset":{"type":"passage","lines":["도서관에서 고양이 보리가 그림책을 펼쳤어요.","책장을 넘기자 보리는 책 속 바다에 풍덩 빠졌어요.","보리는 파란 바다에서 헤엄을 쳤어요.","다음 장에는 하얀 눈 산이 나왔어요. 눈보라가 휘잉 불었어요.","보리는 칙칙폭폭 기차를 타고 눈 산을 빠져나왔어요.","기차에서 내린 보리는 넓은 들판에서 피리를 불었어요.","책을 덮자 보리는 다시 도서관 의자 위에 앉아 있었어요."],"title":"책 속으로 떠난 고양이 보리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L09_challenge#10','kor',1,1,'u7','L09','g1_1_kor_u7_L09_challenge','lesson_challenge','K1-1-u7-C8',4,'essay','teacher','보리가 다음 장에서 갈 곳을 상상해, 알맞은 낱말을 넣어 문장 두 개로 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u7-C8","difficulty":4,"kind":"essay","stem":"보리가 다음 장에서 갈 곳을 상상해, 알맞은 낱말을 넣어 문장 두 개로 써 보세요.","answer_guide":{"answer":"예: 보리는 숲속에 갔어요. 보리가 나무 위에서 노래를 불렀어요.","scoring_points":["갈 곳을 상상해 썼는가","무엇을과 어찌하다가 어울리는가","문장 두 개로 썼는가"]},"explanation":["상상한 곳.","어울리는 낱말.","두 문장."],"asset":{"type":"passage","lines":["도서관에서 고양이 보리가 그림책을 펼쳤어요.","책장을 넘기자 보리는 책 속 바다에 풍덩 빠졌어요.","보리는 파란 바다에서 헤엄을 쳤어요.","다음 장에는 하얀 눈 산이 나왔어요. 눈보라가 휘잉 불었어요.","보리는 칙칙폭폭 기차를 타고 눈 산을 빠져나왔어요.","기차에서 내린 보리는 넓은 들판에서 피리를 불었어요.","책을 덮자 보리는 다시 도서관 의자 위에 앉아 있었어요."],"title":"책 속으로 떠난 고양이 보리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L11_basic#1','kor',1,1,'u7','L11','g1_1_kor_u7_L11_basic','lesson_basic','K1-1-u7-C9',1,'mc','auto','낱말 카드를 놓는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u7-X14']::text[],false,'{"seq":1,"concept":"K1-1-u7-C9","difficulty":1,"kind":"mc","stem":"낱말 카드를 놓는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"누가 → 무엇을 → 어찌하다","correct":true},{"t":"어찌하다 → 누가 → 무엇을","mis":"K1-1-u7-X14"},{"t":"무엇을 → 어찌하다 → 누가","mis":"K1-1-u7-X14"}],"explanation":["누가 → 무엇을 → 어찌하다 차례로 놓아요.","차례를 바꾸면 문장이 어색해져요.","노란색 → 분홍색 → 하늘색 카드 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L11_basic#2','kor',1,1,'u7','L11','g1_1_kor_u7_L11_basic','lesson_basic','K1-1-u7-C9',1,'mc','auto','「누가」 카드는 어느 것인가요?',ARRAY['K1-1-u7-X14']::text[],true,'{"seq":2,"concept":"K1-1-u7-C9","difficulty":1,"kind":"mc","stem":"「누가」 카드는 어느 것인가요?","options":[{"t":"곰이","correct":true},{"t":"그림을","mis":"K1-1-u7-X14"},{"t":"마십니다","mis":"K1-1-u7-X14"}],"explanation":["「곰이」는 누가 카드예요.","「그림을」은 무엇을, 「마십니다」는 어찌하다 카드예요.","「~이·~가」로 끝나는 카드를 찾아요."],"variant_rule":{"alt":[{"stem":"「어찌하다」 카드는 어느 것인가요?","options":[{"t":"마십니다","correct":true},{"t":"동생이","mis":"K1-1-u7-X14"},{"t":"물을","mis":"K1-1-u7-X14"}],"explanation":["「마십니다」는 어찌하다 카드예요.","「동생이」는 누가, 「물을」은 무엇을 카드예요.","하는 일을 나타내는 카드를 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L11_basic#3','kor',1,1,'u7','L11','g1_1_kor_u7_L11_basic','lesson_basic','K1-1-u7-C9',1,'mc','auto','카드로 만든 자연스러운 문장은 어느 것인가요?',ARRAY['K1-1-u7-X11','K1-1-u7-X07']::text[],true,'{"seq":3,"concept":"K1-1-u7-C9","difficulty":1,"kind":"mc","stem":"카드로 만든 자연스러운 문장은 어느 것인가요?","options":[{"t":"여우가 자전거를 탑니다.","correct":true},{"t":"자전거가 여우를 탑니다.","mis":"K1-1-u7-X11"},{"t":"여우가 자전거를 마십니다.","mis":"K1-1-u7-X07"}],"explanation":["「여우가 자전거를 탑니다」가 자연스러워요.","누가와 무엇을을 바꾸거나 어울리지 않는 카드를 놓으면 어색해요.","소리 내어 읽어 어색한지 살펴요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 카드로 만든 자연스러운 문장은 어느 것인가요?","options":[{"t":"토끼가 책을 읽습니다.","correct":true},{"t":"책이 토끼를 읽습니다.","mis":"K1-1-u7-X11"},{"t":"토끼가 책을 마십니다.","mis":"K1-1-u7-X07"}],"explanation":["「토끼가 책을 읽습니다」가 자연스러워요.","누가와 무엇을을 바꾸거나 어울리지 않는 카드를 놓으면 어색해요.","소리 내어 읽어 어색한지 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L11_basic#4','kor',1,1,'u7','L11','g1_1_kor_u7_L11_basic','lesson_basic','K1-1-u7-C9',1,'blank','auto','빈 카드에 알맞은 낱말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L11_basic#5','kor',1,1,'u7','L11','g1_1_kor_u7_L11_basic','lesson_basic','K1-1-u7-C9',2,'match','auto','낱말 카드와 카드 색깔을 이으세요.','{}'::text[],true,'{"seq":5,"concept":"K1-1-u7-C9","difficulty":2,"kind":"match","stem":"낱말 카드와 카드 색깔을 이으세요.","pairs":[{"l":"곰이","r":"노란색(누가)"},{"l":"그림을","r":"분홍색(무엇을)"},{"l":"그립니다","r":"하늘색(어찌하다)"}],"mis":"K1-1-u7-X14","explanation":["누가는 노란색, 무엇을은 분홍색, 어찌하다는 하늘색이에요.","카드의 구실에 따라 색이 달라요.","카드 끝 글자를 보고 구실을 찾아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말 카드와 카드 색깔을 이으세요.","pairs":[{"l":"동생이","r":"노란색(누가)"},{"l":"물을","r":"분홍색(무엇을)"},{"l":"마십니다","r":"하늘색(어찌하다)"}],"explanation":["누가는 노란색, 무엇을은 분홍색, 어찌하다는 하늘색이에요.","카드의 구실에 따라 색이 달라요.","카드 끝 글자를 보고 구실을 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L11_basic#6','kor',1,1,'u7','L11','g1_1_kor_u7_L11_basic','lesson_basic','K1-1-u7-C9',2,'mc','auto','어색한 문장을 자연스럽게 고친 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L11_basic#7','kor',1,1,'u7','L11','g1_1_kor_u7_L11_basic','lesson_basic','K1-1-u7-C9',2,'ox','auto','「곰이 노래를 먹습니다.」처럼 카드가 엉뚱하게 이어지면, 어울리는 카드로 바꾸어 자연스럽게 고쳐요.',ARRAY['K1-1-u7-X07']::text[],false,'{"seq":7,"concept":"K1-1-u7-C9","difficulty":2,"kind":"ox","stem":"「곰이 노래를 먹습니다.」처럼 카드가 엉뚱하게 이어지면, 어울리는 카드로 바꾸어 자연스럽게 고쳐요.","answer":"O","reason_options":[{"t":"「곰이 노래를 부릅니다.」처럼 바꾸면 뜻이 통하니까","correct":true},{"t":"카드로 만든 문장은 고치면 안 되니까","mis":"K1-1-u7-X07"}],"mis":"K1-1-u7-X07","explanation":["엉뚱한 문장은 어울리는 카드로 바꿔 고쳐요.","「노래를 부릅니다」가 어울리는 짝이에요.","고친 문장을 소리 내어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
