INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L11_basic#9','kor',1,1,'u7','L11','g1_1_kor_u7_L11_basic','lesson_basic','K1-1-u7-C9',2,'mc','auto','같은 낱말로 만든 문장 가운데 자연스러운 것은 어느 것인가요?',ARRAY['K1-1-u7-X11']::text[],false,'{"seq":9,"concept":"K1-1-u7-C9","difficulty":2,"kind":"mc","stem":"같은 낱말로 만든 문장 가운데 자연스러운 것은 어느 것인가요?","options":[{"t":"동생이 물을 마십니다.","correct":true},{"t":"물이 동생을 마십니다.","mis":"K1-1-u7-X11"},{"t":"동생을 물이 마십니다.","mis":"K1-1-u7-X11"}],"explanation":["마시는 것은 동생이라 「동생이 물을」이 자연스러워요.","물이 동생을 마실 수는 없어요.","움직이는 쪽을 누가 카드로 놓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
