INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L11_challenge#1','kor',1,1,'u7','L11','g1_1_kor_u7_L11_challenge','lesson_challenge','K1-1-u7-C9',2,'mc','auto','「분홍색(무엇을)」 카드로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u7-X14']::text[],false,'{"seq":1,"concept":"K1-1-u7-C9","difficulty":2,"kind":"mc","stem":"「분홍색(무엇을)」 카드로 알맞은 것은 어느 것인가요?","options":[{"t":"자전거를","correct":true},{"t":"여우가","mis":"K1-1-u7-X14"},{"t":"탑니다","mis":"K1-1-u7-X14"}],"explanation":["「자전거를」은 무엇을 카드예요.","「여우가」는 누가, 「탑니다」는 어찌하다 카드예요.","「~을·~를」로 끝나는 카드를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L11_challenge#2','kor',1,1,'u7','L11','g1_1_kor_u7_L11_challenge','lesson_challenge','K1-1-u7-C10',2,'mc','auto','「무엇을」과 「어찌하다」가 어울리지 않는 것은 어느 것인가요?',ARRAY['K1-1-u7-X07']::text[],true,'{"seq":2,"concept":"K1-1-u7-C10","difficulty":2,"kind":"mc","stem":"「무엇을」과 「어찌하다」가 어울리지 않는 것은 어느 것인가요?","options":[{"t":"연을 마시다","correct":true},{"t":"이를 닦다","mis":"K1-1-u7-X07"},{"t":"책을 읽다","mis":"K1-1-u7-X07"}],"explanation":["「연을」은 「마시다」가 아니라 「날리다」와 어울려요.","「이를 닦다」·「책을 읽다」는 어울리는 짝이에요.","「무엇을」과 이어 소리 내어 읽어 보고 어색한지 살펴요."],"variant_rule":{"colloc":{"ask":"odd","kinds":["do"],"mis":{"do":"X07"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
