INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L11_challenge#5','kor',1,1,'u7','L11','g1_1_kor_u7_L11_challenge','lesson_challenge','K1-1-u7-C9',3,'mc','auto','「누가」 카드만 바꾸어도 자연스러운 문장은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L11_challenge#6','kor',1,1,'u7','L11','g1_1_kor_u7_L11_challenge','lesson_challenge','K1-1-u7-C9',3,'ox','auto','카드를 「누가 → 무엇을 → 어찌하다」 차례로 놓아도 「무엇을」과 「어찌하다」가 어울리지 않으면 어색한 문장이 돼요.',ARRAY['K1-1-u7-X07']::text[],false,'{"seq":6,"concept":"K1-1-u7-C9","difficulty":3,"kind":"ox","stem":"카드를 「누가 → 무엇을 → 어찌하다」 차례로 놓아도 「무엇을」과 「어찌하다」가 어울리지 않으면 어색한 문장이 돼요.","answer":"O","reason_options":[{"t":"「연을 마십니다」처럼 짝이 맞지 않으면 뜻이 통하지 않으니까","correct":true},{"t":"차례만 맞으면 언제나 자연스러운 문장이니까","mis":"K1-1-u7-X07"}],"mis":"K1-1-u7-X07","explanation":["차례와 짝이 모두 맞아야 자연스러워요.","차례만 맞아도 짝이 어색하면 뜻이 통하지 않아요.","무엇을과 어찌하다를 이어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L11_challenge#7','kor',1,1,'u7','L11','g1_1_kor_u7_L11_challenge','lesson_challenge','K1-1-u7-C9',3,'mc','auto','친구와 같은 그림을 보고 서로 다른 카드 문장을 만들었어요. 어떻게 생각하면 좋을까요?',ARRAY['K1-1-u7-X16']::text[],false,'{"seq":7,"concept":"K1-1-u7-C9","difficulty":3,"kind":"mc","stem":"친구와 같은 그림을 보고 서로 다른 카드 문장을 만들었어요. 어떻게 생각하면 좋을까요?","options":[{"t":"그림과 어울리고 뜻이 통하면 둘 다 맞아요","correct":true},{"t":"친구 문장과 같아야만 맞아요","mis":"K1-1-u7-X16"},{"t":"내 문장만 맞아요","mis":"K1-1-u7-X16"}],"explanation":["그림과 어울리고 뜻이 통하면 모두 맞아요.","문장이 서로 달라도 괜찮아요.","그림과 어울리는지, 뜻이 통하는지만 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L11_challenge#8','kor',1,1,'u7','L11','g1_1_kor_u7_L11_challenge','lesson_challenge','K1-1-u7-C9',4,'mc','auto','카드 여섯 장 「곰이」 「토끼가」 「노래를」 「당근을」 「부릅니다」 「먹습니다」로 만든 문장 두 개가 모두 자연스러운 것은 어느 것인가요?',ARRAY['K1-1-u7-X07','K1-1-u7-X14']::text[],false,'{"seq":8,"concept":"K1-1-u7-C9","difficulty":4,"kind":"mc","stem":"카드 여섯 장 「곰이」 「토끼가」 「노래를」 「당근을」 「부릅니다」 「먹습니다」로 만든 문장 두 개가 모두 자연스러운 것은 어느 것인가요?","options":[{"t":"곰이 노래를 부릅니다. · 토끼가 당근을 먹습니다.","correct":true},{"t":"곰이 당근을 부릅니다. · 토끼가 노래를 먹습니다.","mis":"K1-1-u7-X07"},{"t":"부릅니다 곰이 노래를. · 먹습니다 토끼가 당근을.","mis":"K1-1-u7-X14"}],"explanation":["「노래를 부릅니다」, 「당근을 먹습니다」가 어울리는 짝이에요.","짝을 바꾸거나 차례를 뒤집으면 어색해요.","짝과 차례를 모두 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L11_challenge#9','kor',1,1,'u7','L11','g1_1_kor_u7_L11_challenge','lesson_challenge','K1-1-u7-C9',4,'essay','teacher','「누가」 「무엇을」 「어찌하다」 카드를 한 장씩 골라 나만의 자연스러운 문장을 만들어 쓰고, 카드를 어떤 차례로 놓았는지 말해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u7-C9","difficulty":4,"kind":"essay","stem":"「누가」 「무엇을」 「어찌하다」 카드를 한 장씩 골라 나만의 자연스러운 문장을 만들어 쓰고, 카드를 어떤 차례로 놓았는지 말해 보세요.","answer_guide":{"answer":"예: 고양이가 피리를 붑니다. — 노란색 「고양이가」, 분홍색 「피리를」, 하늘색 「붑니다」 차례로 놓았어요.","scoring_points":["세 카드로 자연스러운 문장을 만들었는가","무엇을과 어찌하다가 어울리는가","카드 차례를 바르게 말했는가"]},"explanation":["자연스러운 문장.","어울리는 짝.","카드 차례."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L11_challenge#10','kor',1,1,'u7','L11','g1_1_kor_u7_L11_challenge','lesson_challenge','K1-1-u7-C9',4,'essay','teacher','「하늘이 새를 날아갑니다.」가 어색한 까닭을 쓰고, 자연스럽게 고쳐 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u7-C9","difficulty":4,"kind":"essay","stem":"「하늘이 새를 날아갑니다.」가 어색한 까닭을 쓰고, 자연스럽게 고쳐 써 보세요.","answer_guide":{"answer":"예: 날아가는 것은 새인데 하늘이 날아가는 것처럼 썼어요. → 새가 하늘을 날아갑니다.","scoring_points":["어색한 까닭을 썼는가","누가와 무엇을을 바르게 바꿨는가","자연스러운 문장으로 고쳐 썼는가"]},"explanation":["어색한 까닭.","누가·무엇을.","고친 문장."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_a#1','kor',1,1,'u7','','g1_1_kor_u7_review_a','unit_review','K1-1-u7-C1',1,'mc','auto','요리하던 곰이 「당근!」이라고만 말했어요. 무엇을 하라는 것인지 알 수 있나요?',ARRAY['K1-1-u7-X01']::text[],false,'{"seq":1,"concept":"K1-1-u7-C1","difficulty":1,"kind":"mc","stem":"요리하던 곰이 「당근!」이라고만 말했어요. 무엇을 하라는 것인지 알 수 있나요?","options":[{"t":"알 수 없어요 — 달라는 건지 씻으라는 건지 몰라요","correct":true},{"t":"네, 당근을 먹으라는 뜻이에요","mis":"K1-1-u7-X01"},{"t":"네, 낱말 하나면 뜻이 다 통해요","mis":"K1-1-u7-X01"}],"explanation":["「당근!」만으로는 무엇을 어떻게 하라는지 알 수 없어요.","낱말 하나는 여러 뜻으로 알아들을 수 있어요.","무엇을 어떻게 할지 문장으로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_a#2','kor',1,1,'u7','','g1_1_kor_u7_review_a','unit_review','K1-1-u7-C3',1,'mc','auto','그림에 알맞은 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-1-u7-X03','K1-1-u7-X04']::text[],false,'{"seq":2,"concept":"K1-1-u7-C3","difficulty":1,"kind":"mc","stem":"그림에 알맞은 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"낚시","correct":true},{"t":"낙시","mis":"K1-1-u7-X03"},{"t":"났시","mis":"K1-1-u7-X04"}],"explanation":["물고기를 잡는 일은 「낚시」, 받침이 ㄲ이에요.","받침을 하나만 쓰거나 다른 받침을 쓰면 틀린 글자가 돼요.","받침 자리에 같은 자음자 두 개를 나란히 써요."],"asset":{"type":"scene","icon":"🎣🐟"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_a#3','kor',1,1,'u7','','g1_1_kor_u7_review_a','unit_review','K1-1-u7-C4',1,'mc','auto','그림에 알맞은 낱말은 어느 것인가요?',ARRAY['K1-1-u7-X05','K1-1-u7-X06']::text[],false,'{"seq":3,"concept":"K1-1-u7-C4","difficulty":1,"kind":"mc","stem":"그림에 알맞은 낱말은 어느 것인가요?","options":[{"t":"우산","correct":true},{"t":"우유","mis":"K1-1-u7-X05"},{"t":"모자","mis":"K1-1-u7-X06"}],"explanation":["그림은 비를 막는 우산이에요.","첫 글자만 같거나 그림에 없는 낱말이에요.","끝 글자까지 그림과 맞춰 봐요."],"asset":{"type":"scene","icon":"☂️"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_a#4','kor',1,1,'u7','','g1_1_kor_u7_review_a','unit_review','K1-1-u7-C5',1,'blank','auto','「물을 (     )」에 들어갈 알맞은 말은 어느 것인가요?',ARRAY['K1-1-u7-X07']::text[],true,'{"seq":4,"concept":"K1-1-u7-C5","difficulty":1,"kind":"blank","stem":"「물을 (     )」에 들어갈 알맞은 말은 어느 것인가요?","options":[{"t":"마시다","correct":true},{"t":"날리다","mis":"K1-1-u7-X07"},{"t":"부르다","mis":"K1-1-u7-X07"}],"explanation":["「물을 마시다」가 어울리는 짝이에요.","「날리다」·「부르다」는 「물을」과 어울리지 않아요.","「무엇을」과 이어 소리 내어 읽어 보고 어색한지 살펴요."],"variant_rule":{"colloc":{"ask":"fill","kinds":["do"],"mis":{"do":"X07"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
