INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_a#8','kor',1,1,'u7','','g1_1_kor_u7_review_a','unit_review','K1-1-u7-C10',1,'blank','auto','「모자를 (     )」에 들어갈 알맞은 말은 어느 것인가요?',ARRAY['K1-1-u7-X15']::text[],true,'{"seq":8,"concept":"K1-1-u7-C10","difficulty":1,"kind":"blank","stem":"「모자를 (     )」에 들어갈 알맞은 말은 어느 것인가요?","options":[{"t":"쓰다","correct":true},{"t":"입다","mis":"K1-1-u7-X15"},{"t":"신다","mis":"K1-1-u7-X15"}],"explanation":["「모자를 쓰다」가 어울리는 짝이에요.","「입다」·「신다」는 「모자를」과 어울리지 않아요.","몸의 어디에 어떻게 걸치는지 떠올리며 짝을 지어요."],"variant_rule":{"colloc":{"ask":"fill","kinds":["wear"],"mis":{"wear":"X15"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_a#9','kor',1,1,'u7','','g1_1_kor_u7_review_a','unit_review','K1-1-u7-C2',2,'mc','auto','목이 말라 물을 마시고 싶어요. 뜻이 가장 잘 전해지는 말은 어느 것인가요?',ARRAY['K1-1-u7-X01','K1-1-u7-X02']::text[],false,'{"seq":9,"concept":"K1-1-u7-C2","difficulty":2,"kind":"mc","stem":"목이 말라 물을 마시고 싶어요. 뜻이 가장 잘 전해지는 말은 어느 것인가요?","options":[{"t":"물 좀 주세요.","correct":true},{"t":"물!","mis":"K1-1-u7-X01"},{"t":"물, 컵, 나.","mis":"K1-1-u7-X02"}],"explanation":["「물 좀 주세요.」는 원하는 것을 또렷하게 전해요.","낱말 하나나 늘어놓은 낱말로는 뜻이 흐려요.","하고 싶은 것을 문장으로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
