INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_a#11','kor',1,1,'u7','','g1_1_kor_u7_review_a','unit_review','K1-1-u7-C4',2,'mc','auto','비 오는 날 발에 신는 것이에요. 알맞은 낱말은 어느 것인가요?',ARRAY['K1-1-u7-X05']::text[],false,'{"seq":11,"concept":"K1-1-u7-C4","difficulty":2,"kind":"mc","stem":"비 오는 날 발에 신는 것이에요. 알맞은 낱말은 어느 것인가요?","options":[{"t":"장화","correct":true},{"t":"장갑","mis":"K1-1-u7-X05"},{"t":"장난감","mis":"K1-1-u7-X05"}],"explanation":["발에 신는 것은 장화예요.","첫 글자만 같은 낱말이에요.","끝 글자까지 그림과 맞춰 봐요."],"asset":{"type":"scene","icon":"👢🌧️"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_a#12','kor',1,1,'u7','','g1_1_kor_u7_review_a','unit_review','K1-1-u7-C6',2,'mc','auto','오리를 보고 「무엇은 어떠합니다」로 말한 것은 어느 것인가요?',ARRAY['K1-1-u7-X08','K1-1-u7-X09']::text[],false,'{"seq":12,"concept":"K1-1-u7-C6","difficulty":2,"kind":"mc","stem":"오리를 보고 「무엇은 어떠합니다」로 말한 것은 어느 것인가요?","options":[{"t":"오리는 하얗습니다.","correct":true},{"t":"오리는 과일입니다.","mis":"K1-1-u7-X08"},{"t":"오리를 하얗습니다.","mis":"K1-1-u7-X09"}],"explanation":["오리가 어떠한지 말했어요.","무리를 틀리게 말하거나 틀에 맞지 않는 말이에요.","「무엇은 어떠한가?」 생각해요."],"asset":{"type":"scene","icon":"🦆"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_a#13','kor',1,1,'u7','','g1_1_kor_u7_review_a','unit_review','K1-1-u7-C7',2,'ox','auto','「다람쥐가 먹습니다.」만으로는 다람쥐가 무엇을 먹는지 알 수 없어요.',ARRAY['K1-1-u7-X10']::text[],false,'{"seq":13,"concept":"K1-1-u7-C7","difficulty":2,"kind":"ox","stem":"「다람쥐가 먹습니다.」만으로는 다람쥐가 무엇을 먹는지 알 수 없어요.","answer":"O","reason_options":[{"t":"「무엇을」 조각이 빠졌으니까","correct":true},{"t":"「누가」만 있으면 다 알 수 있으니까","mis":"K1-1-u7-X10"}],"mis":"K1-1-u7-X10","explanation":["「무엇을」이 없어 뜻이 모자라요.","「다람쥐가 도토리를 먹습니다.」처럼 써요.","「무엇을?」 하고 되물어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_a#14','kor',1,1,'u7','','g1_1_kor_u7_review_a','unit_review','K1-1-u7-C8',2,'mc','auto','이야기의 한 장면을 문장으로 바르게 만든 것은 어느 것인가요?',ARRAY['K1-1-u7-X07','K1-1-u7-X12']::text[],false,'{"seq":14,"concept":"K1-1-u7-C8","difficulty":2,"kind":"mc","stem":"이야기의 한 장면을 문장으로 바르게 만든 것은 어느 것인가요?","options":[{"t":"보리가 바다에서 헤엄을 쳤어요.","correct":true},{"t":"보리가 바다에서 피리를 쳤어요.","mis":"K1-1-u7-X07"},{"t":"보리가 도서관에서 기차를 탔어요.","mis":"K1-1-u7-X12"}],"explanation":["보리는 바다에서 헤엄을 쳤어요.","다른 두 보기는 이야기와 맞지 않아요.","누가·어디에서·무엇을 했는지 이야기에서 찾아요."],"asset":{"type":"passage","lines":["도서관에서 고양이 보리가 그림책을 펼쳤어요.","책장을 넘기자 보리는 책 속 바다에 풍덩 빠졌어요.","보리는 파란 바다에서 헤엄을 쳤어요.","다음 장에는 하얀 눈 산이 나왔어요. 눈보라가 휘잉 불었어요.","보리는 칙칙폭폭 기차를 타고 눈 산을 빠져나왔어요.","기차에서 내린 보리는 넓은 들판에서 피리를 불었어요.","책을 덮자 보리는 다시 도서관 의자 위에 앉아 있었어요."],"title":"책 속으로 떠난 고양이 보리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_a#15','kor',1,1,'u7','','g1_1_kor_u7_review_a','unit_review','K1-1-u7-C9',2,'mc','auto','카드로 만든 자연스러운 문장은 어느 것인가요?',ARRAY['K1-1-u7-X11','K1-1-u7-X07']::text[],false,'{"seq":15,"concept":"K1-1-u7-C9","difficulty":2,"kind":"mc","stem":"카드로 만든 자연스러운 문장은 어느 것인가요?","options":[{"t":"여우가 자전거를 탑니다.","correct":true},{"t":"자전거가 여우를 탑니다.","mis":"K1-1-u7-X11"},{"t":"여우가 자전거를 마십니다.","mis":"K1-1-u7-X07"}],"explanation":["「여우가 자전거를 탑니다」가 자연스러워요.","누가와 무엇을을 바꾸거나 어울리지 않는 카드를 놓으면 어색해요.","소리 내어 읽어 어색한지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
