INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_a#21','kor',1,1,'u7','','g1_1_kor_u7_review_a','unit_review','K1-1-u7-C8',3,'mc','auto','「눈보라」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u7-X13']::text[],false,'{"seq":21,"concept":"K1-1-u7-C8","difficulty":3,"kind":"mc","stem":"「눈보라」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"바람에 휘몰아쳐 날리는 눈","correct":true},{"t":"보라색으로 내리는 눈","mis":"K1-1-u7-X13"},{"t":"눈을 감고 보는 것","mis":"K1-1-u7-X13"}],"explanation":["눈보라는 바람에 휘몰아쳐 날리는 눈이에요.","글자 모양만 보고 짐작한 뜻이에요.","낱말이 나온 앞뒤 문장으로 뜻을 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_a#22','kor',1,1,'u7','','g1_1_kor_u7_review_a','unit_review','K1-1-u7-C10',3,'mc','auto','「무엇을」과 「어찌하다」가 어울리지 않는 것은 어느 것인가요?',ARRAY['K1-1-u7-X15']::text[],true,'{"seq":22,"concept":"K1-1-u7-C10","difficulty":3,"kind":"mc","stem":"「무엇을」과 「어찌하다」가 어울리지 않는 것은 어느 것인가요?","options":[{"t":"장갑을 신다","correct":true},{"t":"모자를 쓰다","mis":"K1-1-u7-X15"},{"t":"옷을 입다","mis":"K1-1-u7-X15"}],"explanation":["「장갑을」은 「신다」가 아니라 「끼다」와 어울려요.","「모자를 쓰다」·「옷을 입다」는 어울리는 짝이에요.","몸의 어디에 어떻게 걸치는지 떠올리며 짝을 지어요."],"variant_rule":{"colloc":{"ask":"odd","kinds":["wear","do"],"mis":{"wear":"X15","do":"X07"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_a#23','kor',1,1,'u7','','g1_1_kor_u7_review_a','unit_review','K1-1-u7-C6',4,'mc','auto','두 문장을 모두 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-1-u7-X09','K1-1-u7-X08']::text[],false,'{"seq":23,"concept":"K1-1-u7-C6","difficulty":4,"kind":"mc","stem":"두 문장을 모두 바르게 쓴 것은 어느 것인가요?","options":[{"t":"복숭아는 과일입니다. · 토끼가 당근을 먹습니다.","correct":true},{"t":"복숭아는 과일입니다. · 토끼는 당근을 입니다.","mis":"K1-1-u7-X09"},{"t":"복숭아는 채소입니다. · 토끼가 당근을 먹습니다.","mis":"K1-1-u7-X08"}],"explanation":["두 문장 모두 틀에 맞고 뜻이 바르게 통해요.","두 틀이 섞이거나 무리를 잘못 말한 문장이 끼어 있어요.","어느 틀인지 먼저 정하고 끝까지 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_a#24','kor',1,1,'u7','','g1_1_kor_u7_review_a','unit_review','K1-1-u7-C9',4,'mc','auto','카드 여섯 장 「곰이」 「토끼가」 「노래를」 「당근을」 「부릅니다」 「먹습니다」로 만든 문장 두 개가 모두 자연스러운 것은 어느 것인가요?',ARRAY['K1-1-u7-X07','K1-1-u7-X14']::text[],false,'{"seq":24,"concept":"K1-1-u7-C9","difficulty":4,"kind":"mc","stem":"카드 여섯 장 「곰이」 「토끼가」 「노래를」 「당근을」 「부릅니다」 「먹습니다」로 만든 문장 두 개가 모두 자연스러운 것은 어느 것인가요?","options":[{"t":"곰이 노래를 부릅니다. · 토끼가 당근을 먹습니다.","correct":true},{"t":"곰이 당근을 부릅니다. · 토끼가 노래를 먹습니다.","mis":"K1-1-u7-X07"},{"t":"부릅니다 곰이 노래를. · 먹습니다 토끼가 당근을.","mis":"K1-1-u7-X14"}],"explanation":["「노래를 부릅니다」, 「당근을 먹습니다」가 어울리는 짝이에요.","짝을 바꾸거나 차례를 뒤집으면 어색해요.","짝과 차례를 모두 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_a#25','kor',1,1,'u7','','g1_1_kor_u7_review_a','unit_review','K1-1-u7-C10',4,'mc','auto','「무엇을」과 「어찌하다」가 모두 알맞은 문장은 어느 것인가요?',ARRAY['K1-1-u7-X15']::text[],false,'{"seq":25,"concept":"K1-1-u7-C10","difficulty":4,"kind":"mc","stem":"「무엇을」과 「어찌하다」가 모두 알맞은 문장은 어느 것인가요?","options":[{"t":"나는 모자를 쓰고 장갑을 꼈어요.","correct":true},{"t":"나는 모자를 입고 장갑을 꼈어요.","mis":"K1-1-u7-X15"},{"t":"나는 모자를 쓰고 장갑을 신었어요.","mis":"K1-1-u7-X15"}],"explanation":["모자는 쓰고, 장갑은 껴요.","다른 두 보기는 몸에 걸치는 말 하나를 바꿔 썼어요.","몸 어디에 걸치는지 떠올리며 짝을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_b#1','kor',1,1,'u7','','g1_1_kor_u7_review_b','unit_review','K1-1-u7-C1',1,'mc','auto','운동장에서 친구가 「공!」이라고만 말했어요. 무엇을 하라는 것인지 알 수 있나요?',ARRAY['K1-1-u7-X01']::text[],false,'{"seq":1,"concept":"K1-1-u7-C1","difficulty":1,"kind":"mc","stem":"운동장에서 친구가 「공!」이라고만 말했어요. 무엇을 하라는 것인지 알 수 있나요?","options":[{"t":"알 수 없어요 — 던지라는 건지 비키라는 건지 몰라요","correct":true},{"t":"네, 공을 차라는 뜻이에요","mis":"K1-1-u7-X01"},{"t":"네, 낱말 하나면 뜻이 다 통해요","mis":"K1-1-u7-X01"}],"explanation":["「공!」만으로는 무엇을 어떻게 하라는지 알 수 없어요.","낱말 하나는 여러 뜻으로 알아들을 수 있어요.","무엇을 어떻게 할지 문장으로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_b#2','kor',1,1,'u7','','g1_1_kor_u7_review_b','unit_review','K1-1-u7-C3',1,'mc','auto','그림에 알맞은 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-1-u7-X03','K1-1-u7-X04']::text[],false,'{"seq":2,"concept":"K1-1-u7-C3","difficulty":1,"kind":"mc","stem":"그림에 알맞은 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"깎다","correct":true},{"t":"깍다","mis":"K1-1-u7-X03"},{"t":"깠다","mis":"K1-1-u7-X04"}],"explanation":["손톱을 자르는 일은 「깎다」, 받침이 ㄲ이에요.","받침을 하나만 쓰거나 다른 받침을 쓰면 틀린 글자가 돼요.","받침 자리에 같은 자음자 두 개를 나란히 써요."],"asset":{"type":"scene","icon":"✂️💅"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_b#3','kor',1,1,'u7','','g1_1_kor_u7_review_b','unit_review','K1-1-u7-C4',1,'mc','auto','그림에 알맞은 낱말은 어느 것인가요?',ARRAY['K1-1-u7-X05','K1-1-u7-X06']::text[],false,'{"seq":3,"concept":"K1-1-u7-C4","difficulty":1,"kind":"mc","stem":"그림에 알맞은 낱말은 어느 것인가요?","options":[{"t":"장갑","correct":true},{"t":"장화","mis":"K1-1-u7-X05"},{"t":"양말","mis":"K1-1-u7-X06"}],"explanation":["그림은 손에 끼는 장갑이에요.","첫 글자만 같거나 그림에 없는 낱말이에요.","끝 글자까지 그림과 맞춰 봐요."],"asset":{"type":"scene","icon":"🧤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_b#4','kor',1,1,'u7','','g1_1_kor_u7_review_b','unit_review','K1-1-u7-C5',1,'blank','auto','「연을 (     )」에 들어갈 알맞은 말은 어느 것인가요?',ARRAY['K1-1-u7-X07']::text[],true,'{"seq":4,"concept":"K1-1-u7-C5","difficulty":1,"kind":"blank","stem":"「연을 (     )」에 들어갈 알맞은 말은 어느 것인가요?","options":[{"t":"날리다","correct":true},{"t":"마시다","mis":"K1-1-u7-X07"},{"t":"부르다","mis":"K1-1-u7-X07"}],"explanation":["「연을 날리다」가 어울리는 짝이에요.","「마시다」·「부르다」는 「연을」과 어울리지 않아요.","「무엇을」과 이어 소리 내어 읽어 보고 어색한지 살펴요."],"variant_rule":{"colloc":{"ask":"fill","kinds":["do"],"mis":{"do":"X07"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
