INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_b#9','kor',1,1,'u7','','g1_1_kor_u7_review_b','unit_review','K1-1-u7-C2',2,'mc','auto','방이 깜깜해서 불을 켜 달라고 하고 싶어요. 뜻이 가장 잘 전해지는 말은 어느 것인가요?',ARRAY['K1-1-u7-X01','K1-1-u7-X02']::text[],false,'{"seq":9,"concept":"K1-1-u7-C2","difficulty":2,"kind":"mc","stem":"방이 깜깜해서 불을 켜 달라고 하고 싶어요. 뜻이 가장 잘 전해지는 말은 어느 것인가요?","options":[{"t":"불 좀 켜 줄래?","correct":true},{"t":"불!","mis":"K1-1-u7-X01"},{"t":"불, 방, 켜.","mis":"K1-1-u7-X02"}],"explanation":["「불 좀 켜 줄래?」는 원하는 것을 또렷하게 전해요.","낱말 하나나 늘어놓은 낱말로는 뜻이 흐려요.","하고 싶은 것을 문장으로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
