INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_c#11','kor',1,1,'u7','','g1_1_kor_u7_review_c','unit_review','K1-1-u7-C4',2,'mc','auto','컵에 따라 마시는 하얀 것이에요. 알맞은 낱말은 어느 것인가요?',ARRAY['K1-1-u7-X05']::text[],false,'{"seq":11,"concept":"K1-1-u7-C4","difficulty":2,"kind":"mc","stem":"컵에 따라 마시는 하얀 것이에요. 알맞은 낱말은 어느 것인가요?","options":[{"t":"우유","correct":true},{"t":"우산","mis":"K1-1-u7-X05"},{"t":"우물","mis":"K1-1-u7-X05"}],"explanation":["마시는 하얀 것은 우유예요.","첫 글자만 같은 낱말이에요.","끝 글자까지 그림과 맞춰 봐요."],"asset":{"type":"scene","icon":"🥛"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_c#12','kor',1,1,'u7','','g1_1_kor_u7_review_c','unit_review','K1-1-u7-C6',2,'mc','auto','얼음을 보고 「무엇은 어떠합니다」로 말한 것은 어느 것인가요?',ARRAY['K1-1-u7-X08','K1-1-u7-X09']::text[],false,'{"seq":12,"concept":"K1-1-u7-C6","difficulty":2,"kind":"mc","stem":"얼음을 보고 「무엇은 어떠합니다」로 말한 것은 어느 것인가요?","options":[{"t":"얼음은 차갑습니다.","correct":true},{"t":"얼음은 과일입니다.","mis":"K1-1-u7-X08"},{"t":"얼음을 차갑습니다.","mis":"K1-1-u7-X09"}],"explanation":["얼음이 어떠한지 말했어요.","무리를 틀리게 말하거나 틀에 맞지 않는 말이에요.","「무엇은 어떠한가?」 생각해요."],"asset":{"type":"scene","icon":"🧊"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_c#13','kor',1,1,'u7','','g1_1_kor_u7_review_c','unit_review','K1-1-u7-C7',2,'ox','auto','「고양이가 마십니다.」만으로는 고양이가 무엇을 마시는지 알 수 없어요.',ARRAY['K1-1-u7-X10']::text[],false,'{"seq":13,"concept":"K1-1-u7-C7","difficulty":2,"kind":"ox","stem":"「고양이가 마십니다.」만으로는 고양이가 무엇을 마시는지 알 수 없어요.","answer":"O","reason_options":[{"t":"「무엇을」 조각이 빠졌으니까","correct":true},{"t":"「누가」만 있으면 다 알 수 있으니까","mis":"K1-1-u7-X10"}],"mis":"K1-1-u7-X10","explanation":["「무엇을」이 없어 뜻이 모자라요.","「고양이가 우유를 마십니다.」처럼 써요.","「무엇을?」 하고 되물어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_c#14','kor',1,1,'u7','','g1_1_kor_u7_review_c','unit_review','K1-1-u7-C8',2,'mc','auto','눈 산에서 일어난 일로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u7-X12','K1-1-u7-X07']::text[],false,'{"seq":14,"concept":"K1-1-u7-C8","difficulty":2,"kind":"mc","stem":"눈 산에서 일어난 일로 알맞은 것은 어느 것인가요?","options":[{"t":"눈보라가 휘잉 불었어요","correct":true},{"t":"보리가 눈사람을 만들었어요","mis":"K1-1-u7-X12"},{"t":"눈보라가 피리를 불었어요","mis":"K1-1-u7-X07"}],"explanation":["눈 산에서는 눈보라가 휘잉 불었어요.","다른 두 보기는 이야기와 맞지 않아요.","누가·어디에서·무엇을 했는지 이야기에서 찾아요."],"asset":{"type":"passage","lines":["도서관에서 고양이 보리가 그림책을 펼쳤어요.","책장을 넘기자 보리는 책 속 바다에 풍덩 빠졌어요.","보리는 파란 바다에서 헤엄을 쳤어요.","다음 장에는 하얀 눈 산이 나왔어요. 눈보라가 휘잉 불었어요.","보리는 칙칙폭폭 기차를 타고 눈 산을 빠져나왔어요.","기차에서 내린 보리는 넓은 들판에서 피리를 불었어요.","책을 덮자 보리는 다시 도서관 의자 위에 앉아 있었어요."],"title":"책 속으로 떠난 고양이 보리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_c#15','kor',1,1,'u7','','g1_1_kor_u7_review_c','unit_review','K1-1-u7-C9',2,'mc','auto','카드로 만든 자연스러운 문장은 어느 것인가요?',ARRAY['K1-1-u7-X11','K1-1-u7-X07']::text[],false,'{"seq":15,"concept":"K1-1-u7-C9","difficulty":2,"kind":"mc","stem":"카드로 만든 자연스러운 문장은 어느 것인가요?","options":[{"t":"새가 하늘을 날아갑니다.","correct":true},{"t":"하늘이 새를 날아갑니다.","mis":"K1-1-u7-X11"},{"t":"새가 하늘을 마십니다.","mis":"K1-1-u7-X07"}],"explanation":["「새가 하늘을 날아갑니다」가 자연스러워요.","누가와 무엇을을 바꾸거나 어울리지 않는 카드를 놓으면 어색해요.","소리 내어 읽어 어색한지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_c#16','kor',1,1,'u7','','g1_1_kor_u7_review_c','unit_review','K1-1-u7-C10',2,'blank','auto','「(     ) 신다」에 들어갈 알맞은 말은 어느 것인가요?',ARRAY['K1-1-u7-X15']::text[],true,'{"seq":16,"concept":"K1-1-u7-C10","difficulty":2,"kind":"blank","stem":"「(     ) 신다」에 들어갈 알맞은 말은 어느 것인가요?","options":[{"t":"신발을","correct":true},{"t":"모자를","mis":"K1-1-u7-X15"},{"t":"옷을","mis":"K1-1-u7-X15"}],"explanation":["「신발을 신다」가 어울리는 짝이에요.","「모자를」·「옷을」은 「신다」와 어울리지 않아요.","몸의 어디에 어떻게 걸치는지 떠올리며 짝을 지어요."],"variant_rule":{"colloc":{"ask":"back","kinds":["wear"],"mis":{"wear":"X15"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
