INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_d#21','kor',1,1,'u7','','g1_1_kor_u7_review_d','unit_review','K1-1-u7-C8',3,'mc','auto','「그림책」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u7-X13']::text[],false,'{"seq":21,"concept":"K1-1-u7-C8","difficulty":3,"kind":"mc","stem":"「그림책」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"그림이 많이 들어 있는 책","correct":true},{"t":"그림을 그리는 책상","mis":"K1-1-u7-X13"},{"t":"그림을 걸어 두는 벽","mis":"K1-1-u7-X13"}],"explanation":["그림책은 그림이 많이 들어 있는 책이에요.","글자 모양만 보고 짐작한 뜻이에요.","낱말이 나온 앞뒤 문장으로 뜻을 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_d#22','kor',1,1,'u7','','g1_1_kor_u7_review_d','unit_review','K1-1-u7-C10',3,'mc','auto','「무엇을」과 「어찌하다」가 어울리지 않는 것은 어느 것인가요?',ARRAY['K1-1-u7-X07']::text[],true,'{"seq":22,"concept":"K1-1-u7-C10","difficulty":3,"kind":"mc","stem":"「무엇을」과 「어찌하다」가 어울리지 않는 것은 어느 것인가요?","options":[{"t":"연을 부르다","correct":true},{"t":"손톱을 깎다","mis":"K1-1-u7-X07"},{"t":"그림을 그리다","mis":"K1-1-u7-X07"}],"explanation":["「연을」은 「부르다」가 아니라 「날리다」와 어울려요.","「손톱을 깎다」·「그림을 그리다」는 어울리는 짝이에요.","「무엇을」과 이어 소리 내어 읽어 보고 어색한지 살펴요."],"variant_rule":{"colloc":{"ask":"odd","kinds":["wear","do"],"mis":{"wear":"X15","do":"X07"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_d#23','kor',1,1,'u7','','g1_1_kor_u7_review_d','unit_review','K1-1-u7-C6',4,'mc','auto','두 문장을 모두 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-1-u7-X09','K1-1-u7-X08']::text[],false,'{"seq":23,"concept":"K1-1-u7-C6","difficulty":4,"kind":"mc","stem":"두 문장을 모두 바르게 쓴 것은 어느 것인가요?","options":[{"t":"당근은 채소입니다. · 다람쥐가 도토리를 먹습니다.","correct":true},{"t":"당근은 채소입니다. · 다람쥐는 도토리를 입니다.","mis":"K1-1-u7-X09"},{"t":"당근은 동물입니다. · 다람쥐가 도토리를 먹습니다.","mis":"K1-1-u7-X08"}],"explanation":["두 문장 모두 틀에 맞고 뜻이 바르게 통해요.","두 틀이 섞이거나 무리를 잘못 말한 문장이 끼어 있어요.","어느 틀인지 먼저 정하고 끝까지 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_d#24','kor',1,1,'u7','','g1_1_kor_u7_review_d','unit_review','K1-1-u7-C9',4,'mc','auto','카드 여섯 장 「원숭이가」 「아기가」 「피아노를」 「우유를」 「칩니다」 「마십니다」로 만든 문장 두 개가 모두 자연스러운 것은 어느 것인가요?',ARRAY['K1-1-u7-X07','K1-1-u7-X14']::text[],false,'{"seq":24,"concept":"K1-1-u7-C9","difficulty":4,"kind":"mc","stem":"카드 여섯 장 「원숭이가」 「아기가」 「피아노를」 「우유를」 「칩니다」 「마십니다」로 만든 문장 두 개가 모두 자연스러운 것은 어느 것인가요?","options":[{"t":"원숭이가 피아노를 칩니다. · 아기가 우유를 마십니다.","correct":true},{"t":"원숭이가 우유를 칩니다. · 아기가 피아노를 마십니다.","mis":"K1-1-u7-X07"},{"t":"칩니다 원숭이가 피아노를. · 마십니다 아기가 우유를.","mis":"K1-1-u7-X14"}],"explanation":["「피아노를 칩니다」, 「우유를 마십니다」가 어울리는 짝이에요.","짝을 바꾸거나 차례를 뒤집으면 어색해요.","짝과 차례를 모두 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_review_d#25','kor',1,1,'u7','','g1_1_kor_u7_review_d','unit_review','K1-1-u7-C10',4,'mc','auto','「무엇을」과 「어찌하다」가 모두 알맞은 문장은 어느 것인가요?',ARRAY['K1-1-u7-X15']::text[],false,'{"seq":25,"concept":"K1-1-u7-C10","difficulty":4,"kind":"mc","stem":"「무엇을」과 「어찌하다」가 모두 알맞은 문장은 어느 것인가요?","options":[{"t":"누나가 반지를 끼고 시계를 찼어요.","correct":true},{"t":"누나가 반지를 입고 시계를 찼어요.","mis":"K1-1-u7-X15"},{"t":"누나가 반지를 끼고 시계를 신었어요.","mis":"K1-1-u7-X15"}],"explanation":["반지는 끼고, 시계는 차요.","다른 두 보기는 몸에 걸치는 말 하나를 바꿔 썼어요.","몸 어디에 걸치는지 떠올리며 짝을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
